package engine

import (
	"errors"
	"fmt"
	"maps"
	"math/rand/v2"
	"strings"
	"sync"
	"time"

	"github.com/tylergannon/tractor/graph"
	"github.com/tylergannon/tractor/harness"
)

// ExecutionScope is the engine-owned context for one handler execution.
type ExecutionScope struct {
	Workdir  string
	StageDir string
	Goal     string
	Stop     *StopSignal
}

// Handler executes one graph node.
type Handler interface {
	Execute(graph.Node, []graph.Edge, ExecutionScope, *graph.Graph) (harness.Outcome, *harness.Error)
}

// HandlerFunc adapts a function to Handler.
type HandlerFunc func(graph.Node, []graph.Edge, ExecutionScope, *graph.Graph) (harness.Outcome, *harness.Error)

func (f HandlerFunc) Execute(node graph.Node, offered []graph.Edge, scope ExecutionScope, pipeline *graph.Graph) (harness.Outcome, *harness.Error) {
	return f(node, offered, scope, pipeline)
}

// Registry maps node type strings to handlers.
type Registry struct {
	handlers map[string]Handler
}

// NewRegistry returns a registry containing the non-LLM built-in handlers.
func NewRegistry() *Registry {
	registry := &Registry{handlers: make(map[string]Handler)}
	registry.Register("start", HandlerFunc(startHandler))
	registry.Register("tool", HandlerFunc(toolHandler))
	return registry
}

// Register installs a handler, replacing any handler for the same type.
func (r *Registry) Register(nodeType string, handler Handler) {
	r.handlers[nodeType] = handler
}

// Resolve returns the handler registered for node's explicit type.
func (r *Registry) Resolve(node graph.Node) (Handler, *harness.Error) {
	handler := r.handlers[node.NodeType()]
	if handler == nil {
		return nil, terminalError(fmt.Sprintf("unknown handler type: %s", node.NodeType()))
	}
	return handler, nil
}

func startHandler(graph.Node, []graph.Edge, ExecutionScope, *graph.Graph) (harness.Outcome, *harness.Error) {
	return harness.Outcome{Notes: "run started"}, nil
}

// StopSignal is a one-shot operator-stop signal.
type StopSignal struct {
	once sync.Once
	done chan struct{}
}

// NewStopSignal creates an unset stop signal.
func NewStopSignal() *StopSignal {
	return &StopSignal{done: make(chan struct{})}
}

// Stop sets the signal. Repeated calls have no effect.
func (s *StopSignal) Stop() {
	s.once.Do(func() { close(s.done) })
}

// IsSet reports whether Stop has been called.
func (s *StopSignal) IsSet() bool {
	select {
	case <-s.done:
		return true
	default:
		return false
	}
}

// Wait blocks until Stop is called.
func (s *StopSignal) Wait() {
	<-s.done
}

// ValidateFunc performs the graph validation phase before initialization.
type ValidateFunc func(graph.Graph) error

// RunnerConfig supplies the run paths and the already-configured backend.
type RunnerConfig struct {
	LogsRoot string
	Workdir  string
	Validate ValidateFunc
	Backend  harness.CodergenBackend
	Stop     *StopSignal
}

// RunStatus is the terminal status of a graph walk.
type RunStatus string

const (
	RunCompleted RunStatus = "COMPLETED"
	RunFailed    RunStatus = "FAILED"
)

// RunResult is the run-level verdict.
type RunResult struct {
	Status        RunStatus
	FailureReason string
}

type nodeExecution struct {
	outcome   harness.Outcome
	nextID    string
	runErr    *harness.Error
	attempted bool
	stageDirs []string
}

// Runner executes one graph from its start node.
type Runner struct {
	graph            graph.Graph
	registry         *Registry
	config           RunnerConfig
	stop             *StopSignal
	nodes            map[string]graph.Node
	startID          string
	resumeCheckpoint *Checkpoint
	retryDelay       func(int) time.Duration
	activeMu         sync.Mutex
	active           *activeExecution
}

// NewRunner validates the graph and prepares a runner without creating run files.
func NewRunner(pipeline graph.Graph, registry *Registry, config RunnerConfig) (*Runner, error) {
	return newRunner(pipeline, registry, config)
}

// ResumeRunner validates the graph and prepares a runner from its durable checkpoint.
func ResumeRunner(pipeline graph.Graph, registry *Registry, config RunnerConfig) (*Runner, error) {
	runner, err := newRunner(pipeline, registry, config)
	if err != nil {
		return nil, err
	}
	checkpoint, err := LoadCheckpoint(config.LogsRoot)
	if err != nil {
		return nil, err
	}
	if err := runner.validateResumeCheckpoint(checkpoint); err != nil {
		return nil, err
	}
	runner.resumeCheckpoint = &checkpoint
	return runner, nil
}

func newRunner(pipeline graph.Graph, registry *Registry, config RunnerConfig) (*Runner, error) {
	if strings.TrimSpace(config.LogsRoot) == "" {
		return nil, fmt.Errorf("logs root must not be empty")
	}
	if strings.TrimSpace(config.Workdir) == "" {
		return nil, fmt.Errorf("workdir must not be empty")
	}
	if config.Validate == nil {
		return nil, fmt.Errorf("validate function must not be nil")
	}
	if err := config.Validate(pipeline); err != nil {
		return nil, fmt.Errorf("validate graph: %w", err)
	}
	registry = cloneRegistry(registry)
	stop := config.Stop
	if stop == nil {
		stop = NewStopSignal()
	}
	nodes := make(map[string]graph.Node, len(pipeline.Nodes))
	startID := ""
	startCount := 0
	for _, node := range pipeline.Nodes {
		if node == nil {
			return nil, fmt.Errorf("graph contains a nil node")
		}
		nodes[node.Base().ID] = node
		if node.NodeType() == "start" {
			startID = node.Base().ID
			startCount++
		}
	}
	if startCount != 1 {
		return nil, fmt.Errorf("graph must contain exactly one start node")
	}
	return &Runner{
		graph:      pipeline,
		registry:   registry,
		config:     config,
		stop:       stop,
		nodes:      nodes,
		startID:    startID,
		retryDelay: defaultRetryDelay,
	}, nil
}

func cloneRegistry(registry *Registry) *Registry {
	if registry == nil {
		return NewRegistry()
	}
	cloned := &Registry{handlers: make(map[string]Handler, len(registry.handlers))}
	maps.Copy(cloned.handlers, registry.handlers)
	return cloned
}

// Stop requests that the run end at the next interruption point.
func (r *Runner) Stop() {
	r.stop.Stop()
	if r.config.Backend != nil {
		r.config.Backend.InterruptAll()
	}
}

// Run initializes or restores durable state and walks the graph to completion or failure.
func (r *Runner) Run() (RunResult, error) {
	state := newEngineState()
	currentID := r.startID
	if r.resumeCheckpoint != nil {
		if r.resumeCheckpoint.NextNode == "" {
			if err := cleanupBranchWorktrees(r.config.Workdir, r.config.LogsRoot); err != nil {
				return RunResult{}, err
			}
			return RunResult{Status: RunCompleted}, nil
		}
		state = stateFromCheckpoint(*r.resumeCheckpoint)
		currentID = r.resumeCheckpoint.NextNode
	}
	store, err := openRunStore(r.config.LogsRoot, state)
	if err != nil {
		return RunResult{}, err
	}
	control, manifest, err := r.startControlServer(store)
	if err != nil {
		return RunResult{}, err
	}
	defer func() { _ = control.close() }()
	started := time.Now()
	if err := store.appendTimeline(timelineEvent{
		"type": "PipelineStarted",
		"name": r.graph.Name,
		"id":   manifest.ID,
	}); err != nil {
		return RunResult{}, err
	}
	r.registry.Register("parallel", &parallelHandler{runner: r, state: state, store: store})
	if r.resumeCheckpoint == nil {
		if err := r.saveCheckpoint(store, state.checkpoint("", r.startID, false, r.bindings()), r.startID); err != nil {
			eventErr := store.appendTimeline(timelineEvent{
				"type": "PipelineFailed", "error": err.Error(), "duration": time.Since(started).String(),
			})
			return RunResult{}, errors.Join(err, eventErr)
		}
	}
	result, runErr := r.walk(state, store, currentID)
	duration := time.Since(started).String()
	if runErr != nil {
		if err := store.appendTimeline(timelineEvent{"type": "PipelineFailed", "error": runErr.Error(), "duration": duration}); err != nil {
			return RunResult{}, errors.Join(runErr, err)
		}
		return result, runErr
	}
	if result.Status == RunFailed {
		if err := store.appendTimeline(timelineEvent{"type": "PipelineFailed", "error": result.FailureReason, "duration": duration}); err != nil {
			return RunResult{}, err
		}
		return result, nil
	}
	if err := store.appendTimeline(timelineEvent{"type": "PipelineCompleted", "duration": duration}); err != nil {
		return RunResult{}, err
	}
	return result, nil
}

func (r *Runner) walk(state *engineState, store *runStore, currentID string) (RunResult, error) {
	for {
		node := r.nodes[currentID]
		if node == nil {
			return failed(fmt.Sprintf("unknown node: %s", currentID)), nil
		}
		if node.NodeType() == "exit" {
			if err := r.saveCheckpoint(store, state.checkpoint(currentID, "", false, r.bindings()), currentID); err != nil {
				return RunResult{}, err
			}
			if err := cleanupBranchWorktrees(r.config.Workdir, r.config.LogsRoot); err != nil {
				return RunResult{}, err
			}
			return RunResult{Status: RunCompleted}, nil
		}
		if r.stop.IsSet() {
			return failed("stopped by operator"), nil
		}

		r.beginTopLevel(node.Base().ID, node.NodeType())
		execution, executeErr := r.executeNode(node, state, store, r.config.Workdir)
		r.clearTopLevel(node.Base().ID)
		if executeErr != nil {
			return RunResult{}, executeErr
		}
		if execution.runErr != nil {
			if execution.attempted {
				if err := r.saveCheckpoint(store, state.checkpoint(node.Base().ID, node.Base().ID, true, r.bindings()), node.Base().ID); err != nil {
					return RunResult{}, err
				}
			}
			return failed(execution.runErr.Message), nil
		}
		state.complete(node.Base().ID, execution.outcome.Notes)
		if err := r.saveCheckpoint(store, state.checkpoint(node.Base().ID, execution.nextID, false, r.bindings()), node.Base().ID); err != nil {
			return RunResult{}, err
		}
		currentID = execution.nextID
	}
}

func (r *Runner) saveCheckpoint(store *runStore, checkpoint Checkpoint, nodeID string) error {
	if err := store.saveCheckpoint(checkpoint); err != nil {
		return err
	}
	return store.appendTimeline(timelineEvent{"type": "CheckpointSaved", "node_id": nodeID})
}

func (r *Runner) executeNode(node graph.Node, state *engineState, store *runStore, workdir string) (nodeExecution, error) {
	offered, err := r.offeredSuccessors(node, state)
	if err != nil {
		return nodeExecution{runErr: terminalError(err.Error())}, nil
	}
	if len(offered) == 0 {
		return nodeExecution{runErr: terminalError(fmt.Sprintf("every successor of %s has exhausted its visit budget", node.Base().ID))}, nil
	}
	handler, resolveErr := r.registry.Resolve(node)
	if resolveErr != nil {
		return nodeExecution{runErr: resolveErr}, nil
	}
	outcome, nextID, runErr, attempted, stageDirs, err := r.executeWithRetry(node, handler, offered, state, store, workdir)
	execution := nodeExecution{outcome: outcome, nextID: nextID, runErr: runErr, attempted: attempted, stageDirs: stageDirs}
	if err != nil {
		return execution, err
	}
	return execution, nil
}

func (r *Runner) validateResumeCheckpoint(checkpoint Checkpoint) error {
	if checkpoint.NextNode == "" {
		current := r.nodes[checkpoint.CurrentNode]
		if current == nil || current.NodeType() != "exit" || checkpoint.RetryVisit {
			return fmt.Errorf("checkpoint has no valid continuation")
		}
		return nil
	}
	if r.nodes[checkpoint.NextNode] == nil {
		return fmt.Errorf("checkpoint next node %q is not in the graph", checkpoint.NextNode)
	}
	if checkpoint.CurrentNode == "" {
		if checkpoint.NextNode != r.startID || checkpoint.RetryVisit {
			return fmt.Errorf("checkpoint has an invalid initial continuation")
		}
		return nil
	}
	current := r.nodes[checkpoint.CurrentNode]
	if current == nil {
		return fmt.Errorf("checkpoint current node %q is not in the graph", checkpoint.CurrentNode)
	}
	if current.NodeType() == "exit" {
		return fmt.Errorf("checkpoint continues after exit node %q", checkpoint.CurrentNode)
	}
	if checkpoint.RetryVisit && checkpoint.NextNode != checkpoint.CurrentNode {
		return fmt.Errorf("checkpoint retry continuation does not name current node %q", checkpoint.CurrentNode)
	}
	return nil
}

func (r *Runner) executeWithRetry(
	node graph.Node,
	handler Handler,
	offered []graph.Edge,
	state *engineState,
	store *runStore,
	workdir string,
) (harness.Outcome, string, *harness.Error, bool, []string, error) {
	maxRetries := resolvedMaxRetries(node, r.graph.Defaults)
	if maxRetries < 0 {
		return harness.Outcome{}, "", terminalError("max_retries must be nonnegative"), false, nil, nil
	}
	maxAttempts := maxRetries + 1
	stageDirs := make([]string, 0, maxAttempts)
	for attempt := 1; attempt <= maxAttempts; attempt++ {
		if r.stop.IsSet() {
			return harness.Outcome{}, "", interruptedError("stopped by operator"), attempt > 1, stageDirs, nil
		}
		stage, err := store.allocateStage(node.Base().ID)
		if err != nil {
			return harness.Outcome{}, "", nil, attempt > 1, stageDirs, err
		}
		stageDirs = append(stageDirs, stage.Dir)
		r.setActiveStage(node.Base().ID, stage.Dir)
		stageStarted := time.Now()
		if err := store.appendTimeline(timelineEvent{
			"type":  "StageStarted",
			"name":  node.Base().ID,
			"index": stage.Seq,
		}); err != nil {
			return harness.Outcome{}, "", nil, attempt > 1, stageDirs, err
		}
		if attempt == 1 {
			state.beginVisit(node.Base().ID)
		}
		state.beginAttempt(node.Base().ID)
		outcome, runErr := callHandler(handler, node, offered, ExecutionScope{
			Workdir:  workdir,
			StageDir: stage.Dir,
			Goal:     r.graph.Goal,
			Stop:     r.stop,
		}, &r.graph)
		if runErr == nil {
			if err := stage.complete(outcome); err != nil {
				return harness.Outcome{}, "", nil, true, stageDirs, err
			}
			nextID, err := r.resolveNext(node, outcome, offered)
			if err != nil {
				return outcome, "", terminalError(err.Error()), true, stageDirs, nil
			}
			if err := store.appendTimeline(timelineEvent{
				"type":     "StageCompleted",
				"name":     node.Base().ID,
				"index":    stage.Seq,
				"duration": time.Since(stageStarted).String(),
				"next":     nextID,
			}); err != nil {
				return harness.Outcome{}, "", nil, true, stageDirs, err
			}
			return outcome, nextID, nil, true, stageDirs, nil
		}
		if err := stage.fail(runErr); err != nil {
			return harness.Outcome{}, "", nil, true, stageDirs, err
		}
		willRetry := runErr.Category == harness.ErrorRetryable && attempt < maxAttempts
		if err := store.appendTimeline(timelineEvent{
			"type":       "StageFailed",
			"name":       node.Base().ID,
			"index":      stage.Seq,
			"error":      runErr.Message,
			"will_retry": willRetry,
		}); err != nil {
			return harness.Outcome{}, "", nil, true, stageDirs, err
		}
		if !willRetry {
			return harness.Outcome{}, "", runErr, true, stageDirs, nil
		}
		delay := r.retryDelay(attempt)
		if err := store.appendTimeline(timelineEvent{
			"type":    "StageRetrying",
			"name":    node.Base().ID,
			"index":   stage.Seq,
			"attempt": attempt + 1,
			"delay":   delay.String(),
		}); err != nil {
			return harness.Outcome{}, "", nil, true, stageDirs, err
		}
		if !waitForBackoff(delay, r.stop) {
			return harness.Outcome{}, "", interruptedError("stopped by operator"), true, stageDirs, nil
		}
	}
	panic("unreachable")
}

func resolvedMaxRetries(node graph.Node, defaults graph.Defaults) int {
	var configured int
	var present bool
	var supported bool
	switch current := node.(type) {
	case *graph.CodergenNode:
		supported = true
		configured, present = current.MaxRetries.Value, current.MaxRetries.Present
	case *graph.FanInNode:
		supported = true
		configured, present = current.MaxRetries.Value, current.MaxRetries.Present
	case *graph.CustomNode:
		supported = true
		configured, present = current.MaxRetries.Value, current.MaxRetries.Present
	}
	if !supported {
		return 0
	}
	if present {
		return configured
	}
	if defaults.MaxRetries.Present {
		return defaults.MaxRetries.Value
	}
	return 0
}

func defaultRetryDelay(attempt int) time.Duration {
	return backoffDelay(attempt, rand.Float64())
}

func backoffDelay(attempt int, jitter float64) time.Duration {
	delay := 200 * time.Millisecond
	for step := 1; step < attempt && delay < 60*time.Second; step++ {
		delay *= 2
		if delay > 60*time.Second {
			delay = 60 * time.Second
		}
	}
	return time.Duration(float64(delay) * (0.5 + jitter))
}

func waitForBackoff(delay time.Duration, stop *StopSignal) bool {
	timer := time.NewTimer(delay)
	defer timer.Stop()
	select {
	case <-timer.C:
		return true
	case <-stop.done:
		return false
	}
}

func (r *Runner) offeredSuccessors(node graph.Node, state *engineState) ([]graph.Edge, error) {
	offered := make([]graph.Edge, 0, len(node.Base().Edges))
	for _, edge := range node.Base().Edges {
		target := r.nodes[edge.To]
		if target == nil {
			return nil, fmt.Errorf("edge from %s names unknown node %s", node.Base().ID, edge.To)
		}
		budget := target.Base().MaxVisits
		if budget.Present && state.visits(target.Base().ID) >= budget.Value {
			continue
		}
		offered = append(offered, edge)
	}
	return offered, nil
}

func (r *Runner) bindings() map[string]harness.ThreadBinding {
	if r.config.Backend == nil {
		return map[string]harness.ThreadBinding{}
	}
	return r.config.Backend.Bindings()
}

func (r *Runner) resolveNext(node graph.Node, outcome harness.Outcome, offered []graph.Edge) (string, error) {
	if node.NodeType() == "parallel" {
		join, err := parallelFanIn(r.graph, node.Base().ID)
		if err != nil {
			return "", err
		}
		if outcome.Next == join.ID {
			return join.ID, nil
		}
		return "", fmt.Errorf("parallel handler named invalid fan-in successor: %s", outcome.Next)
	}
	if outcome.Next == "" {
		if len(offered) == 1 {
			return offered[0].To, nil
		}
		return "", fmt.Errorf("handler supplied no choice among %d offered successors", len(offered))
	}
	for _, edge := range offered {
		if edge.To == outcome.Next {
			return outcome.Next, nil
		}
	}
	return "", fmt.Errorf("chooser named an unoffered successor: %s", outcome.Next)
}

func callHandler(handler Handler, node graph.Node, offered []graph.Edge, scope ExecutionScope, pipeline *graph.Graph) (outcome harness.Outcome, runErr *harness.Error) {
	defer func() {
		if recovered := recover(); recovered != nil {
			outcome = harness.Outcome{}
			runErr = terminalError(fmt.Sprintf("handler panic: %v", recovered))
		}
	}()
	return handler.Execute(node, offered, scope, pipeline)
}

func terminalError(message string) *harness.Error {
	return &harness.Error{Category: harness.ErrorTerminal, Message: message}
}

func interruptedError(message string) *harness.Error {
	return &harness.Error{Category: harness.ErrorInterrupted, Message: message}
}

func failed(reason string) RunResult {
	return RunResult{Status: RunFailed, FailureReason: reason}
}

// Package engine executes Tractor graphs and persists their run state.
package engine

import (
	"maps"
	"sync"
	"time"

	"github.com/tylergannon/tractor/harness"
)

// Checkpoint is the durable top-level execution state.
type Checkpoint struct {
	Timestamp      time.Time                        `json:"timestamp"`
	CurrentNode    string                           `json:"current_node"`
	NextNode       string                           `json:"next_node"`
	CompletedNodes []string                         `json:"completed_nodes"`
	NodeVisits     map[string]int                   `json:"node_visits"`
	NodeAttempts   map[string]int                   `json:"node_attempts"`
	Seq            uint64                           `json:"seq"`
	RetryVisit     bool                             `json:"retry_visit"`
	LastStage      string                           `json:"last_stage"`
	LastResponse   string                           `json:"last_response"`
	Sessions       map[string]harness.ThreadBinding `json:"sessions"`
}

type engineState struct {
	mu sync.Mutex

	completedNodes []string
	nodeVisits     map[string]int
	nodeAttempts   map[string]int
	lastStage      string
	lastResponse   string
	seq            uint64
	retryVisit     bool
}

type counterSnapshot struct {
	nodeVisits   map[string]int
	nodeAttempts map[string]int
}

func newEngineState() *engineState {
	return &engineState{
		completedNodes: []string{},
		nodeVisits:     make(map[string]int),
		nodeAttempts:   make(map[string]int),
	}
}

func stateFromCheckpoint(checkpoint Checkpoint) *engineState {
	return &engineState{
		completedNodes: cloneSlice(checkpoint.CompletedNodes),
		nodeVisits:     cloneMap(checkpoint.NodeVisits),
		nodeAttempts:   cloneMap(checkpoint.NodeAttempts),
		lastStage:      checkpoint.LastStage,
		lastResponse:   checkpoint.LastResponse,
		seq:            checkpoint.Seq,
		retryVisit:     checkpoint.RetryVisit,
	}
}

func (s *engineState) checkpoint(currentNode, nextNode string, retryVisit bool, sessions map[string]harness.ThreadBinding) Checkpoint {
	s.mu.Lock()
	defer s.mu.Unlock()
	return Checkpoint{
		CurrentNode:    currentNode,
		NextNode:       nextNode,
		CompletedNodes: cloneSlice(s.completedNodes),
		NodeVisits:     cloneMap(s.nodeVisits),
		NodeAttempts:   cloneMap(s.nodeAttempts),
		Seq:            s.seq,
		RetryVisit:     retryVisit,
		LastStage:      s.lastStage,
		LastResponse:   s.lastResponse,
		Sessions:       cloneMap(sessions),
	}
}

func (s *engineState) beginVisit(nodeID string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.retryVisit {
		s.retryVisit = false
		return
	}
	s.nodeVisits[nodeID]++
}

func (s *engineState) beginAttempt(nodeID string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.nodeAttempts[nodeID]++
}

func (s *engineState) visits(nodeID string) int {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.nodeVisits[nodeID]
}

func (s *engineState) snapshotCounters() counterSnapshot {
	s.mu.Lock()
	defer s.mu.Unlock()
	return counterSnapshot{
		nodeVisits:   cloneMap(s.nodeVisits),
		nodeAttempts: cloneMap(s.nodeAttempts),
	}
}

func (s *engineState) restoreCounters(snapshot counterSnapshot) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.nodeVisits = cloneMap(snapshot.nodeVisits)
	s.nodeAttempts = cloneMap(snapshot.nodeAttempts)
}

func (s *engineState) complete(nodeID, notes string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.completedNodes = append(s.completedNodes, nodeID)
	s.lastStage = nodeID
	s.lastResponse = truncate(notes, 200)
}

func truncate(value string, limit int) string {
	runes := []rune(value)
	if len(runes) <= limit {
		return value
	}
	return string(runes[:limit])
}

func cloneSlice[T any](values []T) []T {
	if values == nil {
		return []T{}
	}
	return append([]T(nil), values...)
}

func cloneMap[K comparable, V any](values map[K]V) map[K]V {
	result := make(map[K]V, len(values))
	maps.Copy(result, values)
	return result
}

package engine

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"sync"
	"time"

	"github.com/tylergannon/tractor/harness"
)

type timelineEvent map[string]any

type runStore struct {
	root  string
	state *engineState

	checkpointMu sync.Mutex
	timelineMu   sync.Mutex
}

type stage struct {
	Seq    uint64
	NodeID string
	Dir    string
	store  *runStore
}

func openRunStore(root string, state *engineState) (*runStore, error) {
	stagesRoot := filepath.Join(root, "stages")
	if err := os.MkdirAll(filepath.Join(stagesRoot, "latest"), 0o755); err != nil {
		return nil, fmt.Errorf("create run directory: %w", err)
	}
	highest, err := recoverStageSequence(stagesRoot)
	if err != nil {
		return nil, fmt.Errorf("recover stage sequence: %w", err)
	}
	state.mu.Lock()
	if highest > state.seq {
		state.seq = highest
	}
	state.mu.Unlock()
	return &runStore{root: root, state: state}, nil
}

// LoadCheckpoint reads the durable state needed to reconstruct a run.
func LoadCheckpoint(root string) (Checkpoint, error) {
	raw, err := os.ReadFile(filepath.Join(root, "checkpoint.json"))
	if err != nil {
		return Checkpoint{}, fmt.Errorf("read checkpoint: %w", err)
	}
	var checkpoint Checkpoint
	if err := json.Unmarshal(raw, &checkpoint); err != nil {
		return Checkpoint{}, fmt.Errorf("decode checkpoint: %w", err)
	}
	checkpoint.CompletedNodes = cloneSlice(checkpoint.CompletedNodes)
	checkpoint.NodeVisits = cloneMap(checkpoint.NodeVisits)
	checkpoint.NodeAttempts = cloneMap(checkpoint.NodeAttempts)
	checkpoint.Sessions = cloneMap(checkpoint.Sessions)
	return checkpoint, nil
}

func (s *runStore) saveCheckpoint(checkpoint Checkpoint) error {
	s.checkpointMu.Lock()
	defer s.checkpointMu.Unlock()

	checkpoint.Timestamp = time.Now().UTC()
	checkpoint.CompletedNodes = cloneSlice(checkpoint.CompletedNodes)
	checkpoint.NodeVisits = cloneMap(checkpoint.NodeVisits)
	checkpoint.NodeAttempts = cloneMap(checkpoint.NodeAttempts)
	checkpoint.Sessions = cloneMap(checkpoint.Sessions)
	raw, err := json.MarshalIndent(checkpoint, "", "  ")
	if err != nil {
		return fmt.Errorf("encode checkpoint: %w", err)
	}
	raw = append(raw, '\n')

	path := filepath.Join(s.root, "checkpoint.json")
	temporary := filepath.Join(s.root, ".checkpoint.json.tmp")
	if err := os.WriteFile(temporary, raw, 0o644); err != nil {
		return fmt.Errorf("write checkpoint: %w", err)
	}
	if err := os.Rename(temporary, path); err != nil {
		_ = os.Remove(temporary)
		return fmt.Errorf("replace checkpoint: %w", err)
	}
	return nil
}

func (s *runStore) appendTimeline(event timelineEvent) error {
	s.timelineMu.Lock()
	defer s.timelineMu.Unlock()
	file, err := os.OpenFile(filepath.Join(s.root, "timeline.jsonl"), os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0o644)
	if err != nil {
		return fmt.Errorf("open timeline: %w", err)
	}
	encodeErr := json.NewEncoder(file).Encode(event)
	closeErr := file.Close()
	if encodeErr != nil {
		return fmt.Errorf("append timeline: %w", encodeErr)
	}
	if closeErr != nil {
		return fmt.Errorf("close timeline: %w", closeErr)
	}
	return nil
}

func (s *runStore) appendSteering(stageDir string, parts []harness.ContentPart) error {
	file, err := os.OpenFile(filepath.Join(stageDir, "steering.jsonl"), os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0o644)
	if err != nil {
		return fmt.Errorf("open steering audit: %w", err)
	}
	encodeErr := json.NewEncoder(file).Encode(struct {
		Timestamp time.Time             `json:"timestamp"`
		Parts     []harness.ContentPart `json:"parts"`
	}{Timestamp: time.Now().UTC(), Parts: parts})
	closeErr := file.Close()
	if encodeErr != nil {
		return fmt.Errorf("append steering audit: %w", encodeErr)
	}
	if closeErr != nil {
		return fmt.Errorf("close steering audit: %w", closeErr)
	}
	return nil
}

func (s *runStore) allocateStage(nodeID string) (stage, error) {
	s.state.mu.Lock()
	defer s.state.mu.Unlock()
	sequence := s.state.seq + 1
	dir := filepath.Join(s.root, "stages", fmt.Sprintf("%06d-%s", sequence, nodeID))
	if err := os.Mkdir(dir, 0o755); err != nil {
		return stage{}, fmt.Errorf("create stage directory: %w", err)
	}
	s.state.seq = sequence
	return stage{Seq: sequence, NodeID: nodeID, Dir: dir, store: s}, nil
}

func (s stage) complete(outcome harness.Outcome) error {
	if err := writeJSON(filepath.Join(s.Dir, "outcome.json"), outcome); err != nil {
		return fmt.Errorf("write outcome: %w", err)
	}
	latest := filepath.Join(s.store.root, "stages", "latest", s.NodeID)
	temporary := latest + ".tmp"
	if err := os.Remove(temporary); err != nil && !os.IsNotExist(err) {
		return fmt.Errorf("prepare latest stage link: %w", err)
	}
	target := filepath.Join("..", filepath.Base(s.Dir))
	if err := os.Symlink(target, temporary); err != nil {
		return fmt.Errorf("create latest stage link: %w", err)
	}
	if err := os.Rename(temporary, latest); err != nil {
		_ = os.Remove(temporary)
		return fmt.Errorf("replace latest stage link: %w", err)
	}
	return nil
}

func (s stage) fail(runErr *harness.Error) error {
	if err := writeJSON(filepath.Join(s.Dir, "error.json"), runErr); err != nil {
		return fmt.Errorf("write stage error: %w", err)
	}
	return nil
}

func writeJSON(path string, value any) error {
	raw, err := json.MarshalIndent(value, "", "  ")
	if err != nil {
		return err
	}
	raw = append(raw, '\n')
	return os.WriteFile(path, raw, 0o644)
}

func recoverStageSequence(stagesRoot string) (uint64, error) {
	entries, err := os.ReadDir(stagesRoot)
	if err != nil {
		return 0, err
	}
	var highest uint64
	for _, entry := range entries {
		if !entry.IsDir() || entry.Name() == "latest" {
			continue
		}
		dash := strings.IndexByte(entry.Name(), '-')
		if dash <= 0 {
			continue
		}
		sequence, parseErr := strconv.ParseUint(entry.Name()[:dash], 10, 64)
		if parseErr == nil && sequence > highest {
			highest = sequence
		}
	}
	return highest, nil
}

package engine

import (
	"bufio"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sync"
	"time"

	"github.com/tylergannon/tractor/graph"
	"github.com/tylergannon/tractor/harness"
	"github.com/tylergannon/tractor/lint"
)

type parallelHandler struct {
	runner *Runner
	state  *engineState
	store  *runStore
}

func (h *parallelHandler) Execute(node graph.Node, offered []graph.Edge, scope ExecutionScope, pipeline *graph.Graph) (harness.Outcome, *harness.Error) {
	parallel, ok := node.(*graph.ParallelNode)
	if !ok {
		return harness.Outcome{}, terminalError(fmt.Sprintf("parallel handler cannot execute node type %s", node.NodeType()))
	}
	limit := 4
	if parallel.MaxParallel.Present {
		limit = parallel.MaxParallel.Value
	}
	if limit <= 0 {
		return harness.Outcome{}, terminalError("max_parallel must be positive")
	}

	join, err := parallelFanIn(*pipeline, parallel.ID)
	if err != nil {
		return harness.Outcome{}, terminalError(err.Error())
	}
	snapshot := h.state.snapshotCounters()
	succeeded := false
	defer func() {
		if !succeeded {
			h.state.restoreCounters(snapshot)
		}
	}()
	if scope.Stop.IsSet() {
		return harness.Outcome{}, interruptedError("stopped by operator")
	}
	parallelStarted := time.Now()
	if err := h.store.appendTimeline(timelineEvent{
		"type":         "ParallelStarted",
		"branch_count": len(offered),
	}); err != nil {
		return harness.Outcome{}, terminalError(err.Error())
	}

	indexOffset, err := segmentIndexOffset(h.store.root)
	if err != nil {
		return harness.Outcome{}, terminalError(err.Error())
	}
	frozen, err := freezeGitWorkspaceWithStop(scope.Workdir, scope.Stop)
	if err != nil {
		return harness.Outcome{}, parallelExecutionError(err)
	}
	branchIDs := make([]string, len(offered))
	for index, edge := range offered {
		branchIDs[index] = edge.To
	}
	worktrees, err := createBranchWorktreesWithStop(frozen, h.store.root, branchIDs, scope.Stop)
	if err != nil {
		return harness.Outcome{}, parallelExecutionError(err)
	}

	results, eventErr := h.runBranches(worktrees, join.ID, limit)
	segmentErr := attributeBranchSegments(h.store.root, indexOffset, results)
	if err := writeJSON(filepath.Join(scope.StageDir, "branches.json"), results); err != nil {
		return harness.Outcome{}, terminalError(fmt.Sprintf("write branch evidence: %v", err))
	}
	if eventErr != nil {
		return harness.Outcome{}, terminalError(eventErr.Error())
	}
	if segmentErr != nil {
		return harness.Outcome{}, terminalError(segmentErr.Error())
	}
	if err := h.store.appendTimeline(timelineEvent{
		"type":         "ParallelCompleted",
		"duration":     time.Since(parallelStarted).String(),
		"branch_count": len(results),
	}); err != nil {
		return harness.Outcome{}, terminalError(err.Error())
	}
	for _, result := range results {
		if result.Error != nil {
			return harness.Outcome{}, result.Error
		}
	}

	succeeded = true
	return harness.Outcome{Next: join.ID, Notes: fmt.Sprintf("%d branches converged", len(results))}, nil
}

func parallelExecutionError(err error) *harness.Error {
	if errors.Is(err, errGitStopped) {
		return interruptedError("stopped by operator")
	}
	return terminalError(err.Error())
}

func (h *parallelHandler) runBranches(worktrees []branchWorktree, joinID string, limit int) ([]BranchResult, error) {
	results := make([]BranchResult, len(worktrees))
	if limit > len(worktrees) {
		limit = len(worktrees)
	}
	jobs := make(chan int)
	var eventMu sync.Mutex
	var eventErr error
	var workers sync.WaitGroup
	workers.Add(limit)
	for range limit {
		go func() {
			defer workers.Done()
			for index := range jobs {
				worktree := worktrees[index]
				branchStarted := time.Now()
				if err := h.store.appendTimeline(timelineEvent{
					"type":   "ParallelBranchStarted",
					"branch": worktree.BranchID,
					"index":  index,
				}); err != nil {
					results[index] = BranchResult{
						BranchID:  worktree.BranchID,
						Error:     terminalError(err.Error()),
						Path:      []string{},
						Workdir:   worktree.Workdir,
						StageDirs: []string{},
						Segments:  []string{},
					}
					eventMu.Lock()
					eventErr = errors.Join(eventErr, err)
					eventMu.Unlock()
					continue
				}
				results[index] = h.runner.walkBranch(worktree.BranchID, joinID, worktree.Workdir, h.state, h.store)
				if err := h.store.appendTimeline(timelineEvent{
					"type":     "ParallelBranchCompleted",
					"branch":   worktree.BranchID,
					"index":    index,
					"duration": time.Since(branchStarted).String(),
				}); err != nil {
					eventMu.Lock()
					eventErr = errors.Join(eventErr, err)
					eventMu.Unlock()
				}
			}
		}()
	}
	for index := range worktrees {
		jobs <- index
	}
	close(jobs)
	workers.Wait()
	return results, eventErr
}

func (r *Runner) walkBranch(currentID, joinID, workdir string, state *engineState, store *runStore) BranchResult {
	result := BranchResult{
		BranchID:  currentID,
		Path:      []string{},
		Workdir:   workdir,
		StageDirs: []string{},
		Segments:  []string{},
	}
	for currentID != joinID {
		node := r.nodes[currentID]
		if node == nil {
			result.Outcome = nil
			result.Error = terminalError(fmt.Sprintf("unknown node: %s", currentID))
			return result
		}
		if node.NodeType() == "exit" {
			result.Outcome = nil
			result.Error = terminalError(fmt.Sprintf("branch reached exit %s before fan-in %s", currentID, joinID))
			return result
		}
		if r.stop.IsSet() {
			result.Outcome = nil
			result.Error = interruptedError("stopped by operator")
			return result
		}

		result.Path = append(result.Path, currentID)
		execution, err := r.executeNode(node, state, store, workdir)
		result.StageDirs = append(result.StageDirs, execution.stageDirs...)
		if execution.outcome.Notes != "" {
			result.Notes = execution.outcome.Notes
		}
		if err != nil {
			result.Outcome = nil
			result.Error = terminalError(err.Error())
			return result
		}
		if execution.runErr != nil {
			result.Outcome = nil
			result.Error = branchError(execution.runErr)
			return result
		}
		outcome := execution.outcome
		result.Outcome = &outcome
		currentID = execution.nextID
	}
	return result
}

func branchError(runErr *harness.Error) *harness.Error {
	if runErr.Category == harness.ErrorInterrupted {
		return &harness.Error{Category: harness.ErrorInterrupted, Message: runErr.Message}
	}
	return terminalError(runErr.Message)
}

func parallelFanIn(pipeline graph.Graph, parallelID string) (*graph.FanInNode, error) {
	var join *graph.FanInNode
	for _, node := range pipeline.Nodes {
		candidate, ok := node.(*graph.FanInNode)
		if !ok {
			continue
		}
		owner, err := lint.ParallelForFanIn(pipeline, candidate.ID)
		if err == nil && owner.ID == parallelID {
			if join != nil {
				return nil, fmt.Errorf("parallel node %q has multiple fan-in nodes", parallelID)
			}
			join = candidate
		}
	}
	if join == nil {
		return nil, fmt.Errorf("parallel node %q has no designated fan-in", parallelID)
	}
	return join, nil
}

func segmentIndexOffset(logsRoot string) (int64, error) {
	info, err := os.Stat(filepath.Join(logsRoot, "events", "index.jsonl"))
	if os.IsNotExist(err) {
		return 0, nil
	}
	if err != nil {
		return 0, fmt.Errorf("inspect run-log index: %w", err)
	}
	return info.Size(), nil
}

func attributeBranchSegments(logsRoot string, offset int64, results []BranchResult) error {
	file, err := os.Open(filepath.Join(logsRoot, "events", "index.jsonl"))
	if os.IsNotExist(err) {
		return nil
	}
	if err != nil {
		return fmt.Errorf("open run-log index: %w", err)
	}
	defer func() { _ = file.Close() }()
	if _, err := file.Seek(offset, 0); err != nil {
		return fmt.Errorf("seek run-log index: %w", err)
	}

	branchByNode := make(map[string]int)
	for index, result := range results {
		for _, nodeID := range result.Path {
			branchByNode[nodeID] = index
		}
	}
	scanner := bufio.NewScanner(file)
	for scanner.Scan() {
		var entry struct {
			NodeID string `json:"node_id"`
			Path   string `json:"path"`
		}
		if err := json.Unmarshal(scanner.Bytes(), &entry); err != nil {
			return fmt.Errorf("decode run-log index: %w", err)
		}
		if index, ok := branchByNode[entry.NodeID]; ok {
			results[index].Segments = append(results[index].Segments, entry.Path)
		}
	}
	if err := scanner.Err(); err != nil {
		return fmt.Errorf("read run-log index: %w", err)
	}
	return nil
}

package engine

import (
	"bufio"
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"time"
)

var errGitStopped = errors.New("git operation stopped")

type gitWorkspaceSnapshot struct {
	repoRoot   string
	commit     string
	workdirRel string
}

type branchWorktree struct {
	BranchID string
	Path     string
	Workdir  string
}

type worktreeInventoryEntry struct {
	Path     string    `json:"path"`
	BranchID string    `json:"branch_id"`
	TS       time.Time `json:"ts"`
}

func freezeGitWorkspace(workdir string) (gitWorkspaceSnapshot, error) {
	return freezeGitWorkspaceWithStop(workdir, nil)
}

func freezeGitWorkspaceWithStop(workdir string, stop *StopSignal) (gitWorkspaceSnapshot, error) {
	inside, err := gitOutputWithStop(workdir, nil, nil, stop, "rev-parse", "--is-inside-work-tree")
	if errors.Is(err, errGitStopped) {
		return gitWorkspaceSnapshot{}, err
	}
	if err != nil || inside != "true" {
		return gitWorkspaceSnapshot{}, fmt.Errorf("parallel execution requires a git worktree")
	}
	repoRoot, err := gitOutputWithStop(workdir, nil, nil, stop, "rev-parse", "--show-toplevel")
	if err != nil {
		return gitWorkspaceSnapshot{}, err
	}
	resolvedWorkdir, err := filepath.EvalSymlinks(workdir)
	if err != nil {
		return gitWorkspaceSnapshot{}, fmt.Errorf("resolve workspace path: %w", err)
	}
	workdirRel, err := filepath.Rel(repoRoot, resolvedWorkdir)
	if err != nil {
		return gitWorkspaceSnapshot{}, fmt.Errorf("map workspace path: %w", err)
	}
	head, err := gitOutputWithStop(repoRoot, nil, nil, stop, "rev-parse", "--verify", "HEAD^{commit}")
	if err != nil {
		return gitWorkspaceSnapshot{}, fmt.Errorf("resolve workspace HEAD: %w", err)
	}

	indexDir, err := os.MkdirTemp("", "tractor-index-")
	if err != nil {
		return gitWorkspaceSnapshot{}, fmt.Errorf("create temporary git index directory: %w", err)
	}
	defer func() { _ = os.RemoveAll(indexDir) }()
	indexPath := filepath.Join(indexDir, "index")
	indexEnv := []string{"GIT_INDEX_FILE=" + indexPath}
	if _, err := gitOutputWithStop(repoRoot, indexEnv, nil, stop, "read-tree", head); err != nil {
		return gitWorkspaceSnapshot{}, fmt.Errorf("seed workspace snapshot: %w", err)
	}
	if _, err := gitOutputWithStop(repoRoot, indexEnv, nil, stop, "add", "-A", "--", "."); err != nil {
		return gitWorkspaceSnapshot{}, fmt.Errorf("stage workspace snapshot: %w", err)
	}
	tree, err := gitOutputWithStop(repoRoot, indexEnv, nil, stop, "write-tree")
	if err != nil {
		return gitWorkspaceSnapshot{}, fmt.Errorf("write workspace snapshot tree: %w", err)
	}

	identityEnv := []string{
		"GIT_AUTHOR_NAME=tractor",
		"GIT_AUTHOR_EMAIL=tractor@localhost",
		"GIT_AUTHOR_DATE=2000-01-01T00:00:00Z",
		"GIT_COMMITTER_NAME=tractor",
		"GIT_COMMITTER_EMAIL=tractor@localhost",
		"GIT_COMMITTER_DATE=2000-01-01T00:00:00Z",
	}
	commit, err := gitOutputWithStop(repoRoot, identityEnv, strings.NewReader("tractor parallel workspace snapshot\n"), stop, "commit-tree", tree, "-p", head)
	if err != nil {
		return gitWorkspaceSnapshot{}, fmt.Errorf("commit workspace snapshot: %w", err)
	}
	return gitWorkspaceSnapshot{repoRoot: repoRoot, commit: commit, workdirRel: workdirRel}, nil
}

func createBranchWorktrees(snapshot gitWorkspaceSnapshot, logsRoot string, branchIDs []string) ([]branchWorktree, error) {
	return createBranchWorktreesWithStop(snapshot, logsRoot, branchIDs, nil)
}

func createBranchWorktreesWithStop(snapshot gitWorkspaceSnapshot, logsRoot string, branchIDs []string, stop *StopSignal) ([]branchWorktree, error) {
	if len(branchIDs) == 0 {
		return nil, nil
	}
	if err := os.MkdirAll(logsRoot, 0o755); err != nil {
		return nil, fmt.Errorf("create logs directory: %w", err)
	}
	fanoutRoot, err := os.MkdirTemp(logsRoot, "worktrees-")
	if err != nil {
		return nil, fmt.Errorf("create fan-out directory: %w", err)
	}
	created := make([]branchWorktree, 0, len(branchIDs))
	for index, branchID := range branchIDs {
		path := filepath.Join(fanoutRoot, fmt.Sprintf("branch-%03d", index+1))
		entry := worktreeInventoryEntry{Path: path, BranchID: branchID, TS: time.Now().UTC()}
		if err := appendWorktreeInventory(logsRoot, entry); err != nil {
			return created, err
		}
		if _, err := gitOutputWithStop(snapshot.repoRoot, nil, nil, stop, "-c", "core.hooksPath=/dev/null", "worktree", "add", "--detach", path, snapshot.commit); err != nil {
			return created, fmt.Errorf("create worktree for branch %q: %w", branchID, err)
		}
		mappedWorkdir := filepath.Join(path, snapshot.workdirRel)
		if err := os.MkdirAll(mappedWorkdir, 0o755); err != nil {
			return created, fmt.Errorf("create branch workdir for %q: %w", branchID, err)
		}
		created = append(created, branchWorktree{BranchID: branchID, Path: path, Workdir: mappedWorkdir})
	}
	return created, nil
}

func appendWorktreeInventory(logsRoot string, entry worktreeInventoryEntry) error {
	file, err := os.OpenFile(filepath.Join(logsRoot, "worktrees.jsonl"), os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0o644)
	if err != nil {
		return fmt.Errorf("open worktree inventory: %w", err)
	}
	encodeErr := json.NewEncoder(file).Encode(entry)
	closeErr := file.Close()
	if encodeErr != nil {
		return fmt.Errorf("append worktree inventory: %w", encodeErr)
	}
	if closeErr != nil {
		return fmt.Errorf("close worktree inventory: %w", closeErr)
	}
	return nil
}

func cleanupBranchWorktrees(workdir, logsRoot string) error {
	entries, err := readWorktreeInventory(logsRoot)
	if err != nil {
		return err
	}
	if len(entries) == 0 {
		return nil
	}
	repoRoot, err := gitOutput(workdir, nil, nil, "rev-parse", "--show-toplevel")
	if err != nil {
		return fmt.Errorf("resolve git worktree for cleanup: %w", err)
	}

	var cleanupErrors []error
	parents := make(map[string]struct{})
	for _, entry := range entries {
		parents[filepath.Dir(entry.Path)] = struct{}{}
		if _, err := gitOutput(repoRoot, nil, nil, "worktree", "remove", "--force", entry.Path); err != nil {
			if _, statErr := os.Stat(entry.Path); os.IsNotExist(statErr) {
				continue
			}
			cleanupErrors = append(cleanupErrors, fmt.Errorf("remove branch worktree %q: %w", entry.Path, err))
		}
	}
	for parent := range parents {
		if err := os.Remove(parent); err != nil && !os.IsNotExist(err) {
			cleanupErrors = append(cleanupErrors, fmt.Errorf("remove fan-out directory %q: %w", parent, err))
		}
	}
	return errors.Join(cleanupErrors...)
}

func readWorktreeInventory(logsRoot string) ([]worktreeInventoryEntry, error) {
	file, err := os.Open(filepath.Join(logsRoot, "worktrees.jsonl"))
	if os.IsNotExist(err) {
		return nil, nil
	}
	if err != nil {
		return nil, fmt.Errorf("open worktree inventory: %w", err)
	}
	defer func() { _ = file.Close() }()

	var entries []worktreeInventoryEntry
	scanner := bufio.NewScanner(file)
	for scanner.Scan() {
		var entry worktreeInventoryEntry
		decoder := json.NewDecoder(bytes.NewReader(scanner.Bytes()))
		decoder.DisallowUnknownFields()
		if err := decoder.Decode(&entry); err != nil {
			return nil, fmt.Errorf("decode worktree inventory: %w", err)
		}
		entries = append(entries, entry)
	}
	if err := scanner.Err(); err != nil {
		return nil, fmt.Errorf("read worktree inventory: %w", err)
	}
	return entries, nil
}

func gitOutput(dir string, extraEnv []string, stdin io.Reader, args ...string) (string, error) {
	return gitOutputWithStop(dir, extraEnv, stdin, nil, args...)
}

func gitOutputWithStop(dir string, extraEnv []string, stdin io.Reader, stop *StopSignal, args ...string) (string, error) {
	if stop != nil && stop.IsSet() {
		return "", errGitStopped
	}
	commandArgs := append([]string{"-C", dir}, args...)
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	if stop != nil {
		go func() {
			select {
			case <-stop.done:
				cancel()
			case <-ctx.Done():
			}
		}()
	}
	command := exec.CommandContext(ctx, "git", commandArgs...)
	command.Env = append(cleanGitEnvironment(os.Environ()), extraEnv...)
	command.Stdin = stdin
	var stdout bytes.Buffer
	var stderr bytes.Buffer
	command.Stdout = &stdout
	command.Stderr = &stderr
	err := command.Run()
	trimmed := strings.TrimSpace(stdout.String())
	if stop != nil && stop.IsSet() {
		return "", errGitStopped
	}
	if err != nil {
		diagnostic := strings.TrimSpace(stderr.String())
		if diagnostic == "" {
			return "", fmt.Errorf("git %s: %w", strings.Join(args, " "), err)
		}
		return "", fmt.Errorf("git %s: %s: %w", strings.Join(args, " "), diagnostic, err)
	}
	return trimmed, nil
}

func cleanGitEnvironment(environment []string) []string {
	local := map[string]struct{}{
		"GIT_ALTERNATE_OBJECT_DIRECTORIES": {},
		"GIT_COMMON_DIR":                   {},
		"GIT_CONFIG":                       {},
		"GIT_CONFIG_COUNT":                 {},
		"GIT_CONFIG_PARAMETERS":            {},
		"GIT_DIR":                          {},
		"GIT_GRAFT_FILE":                   {},
		"GIT_IMPLICIT_WORK_TREE":           {},
		"GIT_INDEX_FILE":                   {},
		"GIT_NO_REPLACE_OBJECTS":           {},
		"GIT_OBJECT_DIRECTORY":             {},
		"GIT_PREFIX":                       {},
		"GIT_REPLACE_REF_BASE":             {},
		"GIT_SHALLOW_FILE":                 {},
		"GIT_WORK_TREE":                    {},
	}
	filtered := make([]string, 0, len(environment))
	for _, item := range environment {
		name, _, _ := strings.Cut(item, "=")
		if _, found := local[name]; !found {
			filtered = append(filtered, item)
		}
	}
	return filtered
}

package engine

import (
	"crypto/rand"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net"
	"net/http"
	"os"
	"path/filepath"
	"time"

	"github.com/tylergannon/tractor/harness"
)

type runManifest struct {
	ID            string    `json:"id"`
	Name          string    `json:"name"`
	Goal          string    `json:"goal"`
	StartedAt     time.Time `json:"started_at"`
	ControlSocket string    `json:"control_socket"`
}

type activeExecution struct {
	nodeID   string
	nodeType string
	stageDir string
}

type controlServer struct {
	server        *http.Server
	socketPath    string
	temporaryRoot string
}

func (r *Runner) startControlServer(store *runStore) (*controlServer, runManifest, error) {
	socketPath := filepath.Join(store.root, "control.sock")
	temporaryRoot := ""
	if len(socketPath) >= 100 {
		var err error
		temporaryRoot, err = os.MkdirTemp("", "tractor-control-")
		if err != nil {
			return nil, runManifest{}, fmt.Errorf("create control socket directory: %w", err)
		}
		socketPath = filepath.Join(temporaryRoot, "control.sock")
	}
	if err := os.Remove(socketPath); err != nil && !os.IsNotExist(err) {
		if temporaryRoot != "" {
			_ = os.RemoveAll(temporaryRoot)
		}
		return nil, runManifest{}, fmt.Errorf("remove stale control socket: %w", err)
	}
	listener, err := net.Listen("unix", socketPath)
	if err != nil {
		if temporaryRoot != "" {
			_ = os.RemoveAll(temporaryRoot)
		}
		return nil, runManifest{}, fmt.Errorf("listen on control socket: %w", err)
	}

	manifest, err := r.loadOrCreateManifest(socketPath)
	if err != nil {
		_ = listener.Close()
		_ = os.Remove(socketPath)
		if temporaryRoot != "" {
			_ = os.RemoveAll(temporaryRoot)
		}
		return nil, runManifest{}, err
	}
	server := &http.Server{Handler: http.HandlerFunc(func(response http.ResponseWriter, request *http.Request) {
		r.serveControl(store, response, request)
	})}
	control := &controlServer{server: server, socketPath: socketPath, temporaryRoot: temporaryRoot}
	go func() { _ = server.Serve(listener) }()
	return control, manifest, nil
}

func (r *Runner) loadOrCreateManifest(socketPath string) (runManifest, error) {
	path := filepath.Join(r.config.LogsRoot, "manifest.json")
	manifest := runManifest{}
	if raw, err := os.ReadFile(path); err == nil {
		if err := json.Unmarshal(raw, &manifest); err != nil {
			return runManifest{}, fmt.Errorf("decode run manifest: %w", err)
		}
	} else if !os.IsNotExist(err) {
		return runManifest{}, fmt.Errorf("read run manifest: %w", err)
	}
	if manifest.ID == "" {
		id, err := newRunID()
		if err != nil {
			return runManifest{}, err
		}
		manifest.ID = id
		manifest.StartedAt = time.Now().UTC()
	}
	manifest.Name = r.graph.Name
	manifest.Goal = r.graph.Goal
	manifest.ControlSocket = socketPath
	if err := writeJSON(path, manifest); err != nil {
		return runManifest{}, fmt.Errorf("write run manifest: %w", err)
	}
	return manifest, nil
}

func newRunID() (string, error) {
	var value [16]byte
	if _, err := rand.Read(value[:]); err != nil {
		return "", fmt.Errorf("generate run ID: %w", err)
	}
	return hex.EncodeToString(value[:]), nil
}

func (r *Runner) serveControl(store *runStore, response http.ResponseWriter, request *http.Request) {
	if request.URL.Path != "/steer" {
		response.WriteHeader(http.StatusNotFound)
		return
	}
	if request.Method != http.MethodPost {
		response.WriteHeader(http.StatusMethodNotAllowed)
		return
	}
	decoder := json.NewDecoder(request.Body)
	decoder.DisallowUnknownFields()
	var parts []harness.ContentPart
	if err := decoder.Decode(&parts); err != nil || harness.ValidateContentParts(parts) != nil {
		response.WriteHeader(http.StatusBadRequest)
		return
	}
	if err := decoder.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
		response.WriteHeader(http.StatusBadRequest)
		return
	}

	r.activeMu.Lock()
	defer r.activeMu.Unlock()
	if r.active == nil || r.active.stageDir == "" || r.active.nodeType == "parallel" || r.config.Backend == nil {
		response.WriteHeader(http.StatusConflict)
		return
	}
	if r.config.Backend.Steer(parts) != harness.SteerAccepted {
		response.WriteHeader(http.StatusConflict)
		return
	}
	if err := store.appendSteering(r.active.stageDir, parts); err != nil {
		response.WriteHeader(http.StatusInternalServerError)
		return
	}
	response.WriteHeader(http.StatusOK)
}

func (r *Runner) beginTopLevel(nodeID, nodeType string) {
	r.activeMu.Lock()
	defer r.activeMu.Unlock()
	r.active = &activeExecution{nodeID: nodeID, nodeType: nodeType}
}

func (r *Runner) setActiveStage(nodeID, stageDir string) {
	r.activeMu.Lock()
	defer r.activeMu.Unlock()
	if r.active != nil && r.active.nodeID == nodeID {
		r.active.stageDir = stageDir
	}
}

func (r *Runner) clearTopLevel(nodeID string) {
	r.activeMu.Lock()
	defer r.activeMu.Unlock()
	if r.active != nil && r.active.nodeID == nodeID {
		r.active = nil
	}
}

func (s *controlServer) close() error {
	serverErr := s.server.Close()
	removeErr := os.Remove(s.socketPath)
	if os.IsNotExist(removeErr) {
		removeErr = nil
	}
	var temporaryErr error
	if s.temporaryRoot != "" {
		temporaryErr = os.RemoveAll(s.temporaryRoot)
	}
	return errors.Join(serverErr, removeErr, temporaryErr)
}

package engine

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"

	jsonschema "github.com/tylergannon/go-gen-jsonschema"
	"github.com/tylergannon/tractor/graph"
	"github.com/tylergannon/tractor/harness"
)

// CodergenConfig supplies the backend and implementation-level model defaults.
type CodergenConfig struct {
	Backend                harness.CodergenBackend
	DefaultModel           string
	DefaultProvider        string
	DefaultReasoningEffort string
}

// CodergenHandler executes codergen nodes through a CodergenBackend.
type CodergenHandler struct {
	config CodergenConfig
}

// NewCodergenHandler constructs a codergen handler. A nil backend enables simulation.
func NewCodergenHandler(config CodergenConfig) *CodergenHandler {
	return &CodergenHandler{config: config}
}

// Execute renders and executes one codergen turn.
func (h *CodergenHandler) Execute(node graph.Node, offered []graph.Edge, scope ExecutionScope, pipeline *graph.Graph) (harness.Outcome, *harness.Error) {
	codergen, ok := node.(*graph.CodergenNode)
	if !ok {
		return harness.Outcome{}, terminalError(fmt.Sprintf("codergen handler cannot execute node type %s", node.NodeType()))
	}

	prompt := codergen.PromptValue(codergen.DisplayLabel())
	prompt = strings.ReplaceAll(prompt, "$goal", scope.Goal)
	return h.executeTurn(codergen, &codergen.LLMNodeFields, offered, scope, pipeline, prompt)
}

func (h *CodergenHandler) executeTurn(node graph.Node, fields *graph.LLMNodeFields, offered []graph.Edge, scope ExecutionScope, pipeline *graph.Graph, prompt string) (harness.Outcome, *harness.Error) {
	if err := os.WriteFile(filepath.Join(scope.StageDir, "prompt.md"), []byte(prompt), 0o644); err != nil {
		return harness.Outcome{}, terminalError(fmt.Sprintf("write prompt: %v", err))
	}

	turn, err := h.turn(node, fields, offered, scope, pipeline, prompt)
	if err != nil {
		return harness.Outcome{}, err
	}
	if validationErr := harness.ValidateCodergenTurn(turn); validationErr != nil {
		return harness.Outcome{}, validationErr
	}
	var outcome harness.Outcome
	if h.config.Backend == nil {
		outcome = harness.Outcome{Notes: "[Simulated] Stage completed: " + node.Base().ID}
		if len(offered) > 1 {
			outcome.Next = offered[0].To
		}
	} else {
		var runErr *harness.Error
		outcome, runErr = h.config.Backend.Run(turn)
		if runErr != nil {
			return harness.Outcome{}, runErr
		}
	}

	if err := writeResponse(filepath.Join(scope.StageDir, "response.md"), outcome); err != nil {
		return harness.Outcome{}, terminalError(fmt.Sprintf("write response: %v", err))
	}
	return outcome, nil
}

func (h *CodergenHandler) turn(node graph.Node, fields *graph.LLMNodeFields, offered []graph.Edge, scope ExecutionScope, pipeline *graph.Graph, prompt string) (harness.CodergenTurn, *harness.Error) {
	model := resolveString(fields.LLMModel, pipeline.Defaults.LLMModel, h.config.DefaultModel)
	provider := resolveProvider(fields.LLMProvider, pipeline.Defaults.LLMProvider, h.config.DefaultProvider, model)
	reasoningDefault := h.config.DefaultReasoningEffort
	if reasoningDefault == "" {
		reasoningDefault = "high"
	}
	reasoning := resolveString(fields.ReasoningEffort, pipeline.Defaults.ReasoningEffort, reasoningDefault)
	fidelity := resolveString(fields.Fidelity, pipeline.Defaults.Fidelity, string(harness.FidelityCompacted))
	threadKey := ""
	if fidelity != string(harness.FidelityNone) {
		threadKey = fields.ThreadKey(node.Base().ID)
	}
	timeout, timeoutErr := resolveTimeout(fields.Timeout, pipeline.Defaults.Timeout)
	if timeoutErr != nil {
		return harness.CodergenTurn{}, terminalError(timeoutErr.Error())
	}
	schema, schemaErr := choiceSchema(offered, pipeline)
	if schemaErr != nil {
		return harness.CodergenTurn{}, terminalError(schemaErr.Error())
	}
	return harness.CodergenTurn{
		NodeID:          node.Base().ID,
		Parts:           []harness.ContentPart{{Type: harness.ContentPartText, Text: prompt}},
		OutputSchema:    schema,
		Model:           model,
		Provider:        provider,
		ReasoningEffort: reasoning,
		Fidelity:        harness.FidelityMode(fidelity),
		ThreadKey:       threadKey,
		Workdir:         scope.Workdir,
		Timeout:         timeout,
	}, nil
}

func resolveString(nodeValue, fileValue jsonschema.Optional[string], systemValue string) string {
	if nodeValue.Present {
		return nodeValue.Value
	}
	if fileValue.Present {
		return fileValue.Value
	}
	return systemValue
}

func resolveProvider(nodeValue, fileValue jsonschema.Optional[string], systemValue, model string) string {
	if nodeValue.Present {
		return nodeValue.Value
	}
	if fileValue.Present {
		return fileValue.Value
	}
	if systemValue != "" {
		return systemValue
	}
	return DetectProvider(model)
}

func resolveTimeout(nodeValue, fileValue jsonschema.Optional[graph.Duration]) (time.Duration, error) {
	if nodeValue.Present {
		return nodeValue.Value.Parse()
	}
	if fileValue.Present {
		return fileValue.Value.Parse()
	}
	return 0, nil
}

// DetectProvider returns the provider implied by a known provider-native model name.
func DetectProvider(model string) string {
	lower := strings.ToLower(model)
	switch {
	case strings.HasPrefix(lower, "claude"):
		return "anthropic"
	case strings.HasPrefix(lower, "gpt-"), strings.HasPrefix(lower, "o1"), strings.HasPrefix(lower, "o3"), strings.HasPrefix(lower, "o4"), strings.Contains(lower, "codex"):
		return "openai"
	case strings.HasPrefix(lower, "gemini"):
		return "gemini"
	default:
		return ""
	}
}

type outputSchema struct {
	Type                 string           `json:"type"`
	Properties           schemaProperties `json:"properties"`
	Required             []string         `json:"required"`
	AdditionalProperties bool             `json:"additionalProperties"`
}

type schemaProperties struct {
	Next  *schemaProperty `json:"next,omitempty"`
	Notes schemaProperty  `json:"notes"`
}

type schemaProperty struct {
	Type        string   `json:"type"`
	Enum        []string `json:"enum,omitempty"`
	Description string   `json:"description"`
}

func choiceSchema(offered []graph.Edge, pipeline *graph.Graph) (json.RawMessage, error) {
	properties := schemaProperties{
		Notes: schemaProperty{Type: "string", Description: "Your account of this stage."},
	}
	required := []string{"notes"}
	if len(offered) > 1 {
		targets := make([]string, len(offered))
		for index, edge := range offered {
			targets[index] = edge.To
		}
		properties.Next = &schemaProperty{
			Type:        "string",
			Enum:        targets,
			Description: describeRoutes(offered, pipeline),
		}
		required = []string{"next", "notes"}
	}
	encoded, err := json.Marshal(outputSchema{
		Type:                 "object",
		Properties:           properties,
		Required:             required,
		AdditionalProperties: false,
	})
	if err != nil {
		return nil, fmt.Errorf("encode choice schema: %w", err)
	}
	return encoded, nil
}

func describeRoutes(offered []graph.Edge, pipeline *graph.Graph) string {
	clauses := make([]string, len(offered))
	for index, edge := range offered {
		description := strings.TrimSpace(edge.Condition)
		if description == "" {
			if target, ok := pipeline.NodeByID(edge.To); ok {
				description = strings.TrimSpace(target.Base().DisplayLabel())
			}
			if description == "" {
				description = edge.To
			}
		}
		clauses[index] = description + ": " + edge.To
	}
	return "Choose the next stage. " + strings.Join(clauses, "; ")
}

func writeResponse(path string, outcome harness.Outcome) error {
	var response strings.Builder
	response.WriteString("---\n")
	if outcome.Next != "" {
		response.WriteString("next: ")
		response.WriteString(outcome.Next)
		response.WriteByte('\n')
	}
	response.WriteString("---\n")
	response.WriteString(outcome.Notes)
	return os.WriteFile(path, []byte(response.String()), 0o644)
}

package engine

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"

	"github.com/tylergannon/tractor/graph"
	"github.com/tylergannon/tractor/harness"
	"github.com/tylergannon/tractor/lint"
)

// BranchResult is the durable evidence produced for one parallel branch.
type BranchResult struct {
	BranchID  string           `json:"branch_id"`
	Outcome   *harness.Outcome `json:"outcome,omitempty"`
	Error     *harness.Error   `json:"error,omitempty"`
	Notes     string           `json:"notes"`
	Path      []string         `json:"path"`
	Workdir   string           `json:"workdir"`
	StageDirs []string         `json:"stage_dirs"`
	Segments  []string         `json:"segments"`
}

// MarshalJSON keeps required collection fields as arrays for strict readers.
func (r BranchResult) MarshalJSON() ([]byte, error) {
	type branchResult BranchResult
	normalized := branchResult(r)
	if normalized.Path == nil {
		normalized.Path = []string{}
	}
	if normalized.StageDirs == nil {
		normalized.StageDirs = []string{}
	}
	if normalized.Segments == nil {
		normalized.Segments = []string{}
	}
	return json.Marshal(normalized)
}

// UnmarshalJSON enforces the complete, closed BranchResult evidence shape.
func (r *BranchResult) UnmarshalJSON(data []byte) error {
	type wireBranchResult struct {
		BranchID  *string         `json:"branch_id"`
		Outcome   json.RawMessage `json:"outcome"`
		Error     json.RawMessage `json:"error"`
		Notes     *string         `json:"notes"`
		Path      *[]string       `json:"path"`
		Workdir   *string         `json:"workdir"`
		StageDirs *[]string       `json:"stage_dirs"`
		Segments  *[]string       `json:"segments"`
	}
	var wire wireBranchResult
	if err := decodeStrictJSON(data, &wire); err != nil {
		return err
	}
	if wire.BranchID == nil || wire.Notes == nil || wire.Path == nil || wire.Workdir == nil || wire.StageDirs == nil || wire.Segments == nil {
		return fmt.Errorf("branch result is missing a required field")
	}
	if strings.TrimSpace(*wire.BranchID) == "" {
		return fmt.Errorf("branch_id must not be empty")
	}
	if strings.TrimSpace(*wire.Workdir) == "" {
		return fmt.Errorf("workdir must not be empty")
	}
	outcomePresent := len(wire.Outcome) != 0
	errorPresent := len(wire.Error) != 0
	if outcomePresent == errorPresent {
		return fmt.Errorf("branch result must contain exactly one of outcome or error")
	}

	result := BranchResult{
		BranchID:  *wire.BranchID,
		Notes:     *wire.Notes,
		Path:      *wire.Path,
		Workdir:   *wire.Workdir,
		StageDirs: *wire.StageDirs,
		Segments:  *wire.Segments,
	}
	if outcomePresent {
		if bytes.Equal(bytes.TrimSpace(wire.Outcome), []byte("null")) {
			return fmt.Errorf("outcome must not be null")
		}
		var encoded struct {
			Next  string  `json:"next"`
			Notes *string `json:"notes"`
		}
		if err := decodeStrictJSON(wire.Outcome, &encoded); err != nil {
			return fmt.Errorf("decode outcome: %w", err)
		}
		if encoded.Notes == nil {
			return fmt.Errorf("outcome is missing notes")
		}
		result.Outcome = &harness.Outcome{Next: encoded.Next, Notes: *encoded.Notes}
	} else {
		if bytes.Equal(bytes.TrimSpace(wire.Error), []byte("null")) {
			return fmt.Errorf("error must not be null")
		}
		var runErr harness.Error
		if err := decodeStrictJSON(wire.Error, &runErr); err != nil {
			return fmt.Errorf("decode error: %w", err)
		}
		if !runErr.Valid() {
			return fmt.Errorf("branch error is invalid")
		}
		result.Error = &runErr
	}
	*r = result
	return nil
}

// FanInHandler evaluates branch evidence through the codergen path.
type FanInHandler struct {
	codergen *CodergenHandler
}

// NewFanInHandler constructs a fan-in handler with the codergen configuration.
func NewFanInHandler(config CodergenConfig) *FanInHandler {
	return &FanInHandler{codergen: NewCodergenHandler(config)}
}

// Execute loads the owning parallel's evidence and runs the fan-in turn.
func (h *FanInHandler) Execute(node graph.Node, offered []graph.Edge, scope ExecutionScope, pipeline *graph.Graph) (harness.Outcome, *harness.Error) {
	join, ok := node.(*graph.FanInNode)
	if !ok {
		return harness.Outcome{}, terminalError(fmt.Sprintf("fan-in handler cannot execute node type %s", node.NodeType()))
	}
	owner, err := lint.ParallelForFanIn(*pipeline, join.ID)
	if err != nil {
		return harness.Outcome{}, terminalError(err.Error())
	}
	evidencePath := filepath.Join(filepath.Dir(scope.StageDir), "latest", owner.ID, "branches.json")
	results, err := readBranchResults(evidencePath)
	if err != nil {
		return harness.Outcome{}, terminalError(fmt.Sprintf("read branch evidence for %s: %v", owner.ID, err))
	}
	branchRoots := make(map[string]struct{}, len(owner.Edges))
	for _, edge := range owner.Edges {
		branchRoots[edge.To] = struct{}{}
	}
	for _, result := range results {
		if _, ok := branchRoots[result.BranchID]; !ok {
			return harness.Outcome{}, terminalError(fmt.Sprintf("branch evidence for %s names unknown branch %q", owner.ID, result.BranchID))
		}
	}

	prompt := ""
	if join.Prompt.Present {
		prompt = join.Prompt.Value
	}
	if prompt == "" {
		prompt = "Evaluate the results of the parallel branches."
	}
	prompt = strings.ReplaceAll(prompt, "$goal", scope.Goal)
	prompt += "\n\n" + renderBranchResults(results)
	return h.codergen.executeTurn(join, &join.LLMNodeFields, offered, scope, pipeline, prompt)
}

func readBranchResults(path string) ([]BranchResult, error) {
	raw, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	var results []BranchResult
	if err := decodeStrictJSON(raw, &results); err != nil {
		return nil, err
	}
	if len(results) == 0 {
		return nil, fmt.Errorf("branches.json must contain at least one branch result")
	}
	seen := make(map[string]struct{}, len(results))
	for _, result := range results {
		if _, duplicate := seen[result.BranchID]; duplicate {
			return nil, fmt.Errorf("duplicate branch_id %q", result.BranchID)
		}
		seen[result.BranchID] = struct{}{}
	}
	return results, nil
}

func renderBranchResults(results []BranchResult) string {
	var rendered strings.Builder
	for index, result := range results {
		if index > 0 {
			rendered.WriteString("\n\n")
		}
		fmt.Fprintf(&rendered, "Branch ID: %s\nNotes: %s\nWorktree: %s", result.BranchID, result.Notes, result.Workdir)
	}
	return rendered.String()
}

func decodeStrictJSON(data []byte, target any) error {
	decoder := json.NewDecoder(bytes.NewReader(data))
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(target); err != nil {
		return err
	}
	if err := decoder.Decode(&struct{}{}); err != io.EOF {
		if err == nil {
			return fmt.Errorf("unexpected trailing JSON value")
		}
		return err
	}
	return nil
}

package engine

import (
	"context"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"syscall"
	"time"

	"github.com/tylergannon/tractor/graph"
	"github.com/tylergannon/tractor/harness"
)

var (
	errToolStopped  = errors.New("tool command stopped")
	errToolTimedOut = errors.New("tool command timed out")
)

func toolHandler(node graph.Node, offered []graph.Edge, scope ExecutionScope, _ *graph.Graph) (harness.Outcome, *harness.Error) {
	tool, ok := node.(*graph.ToolNode)
	if !ok {
		return harness.Outcome{}, terminalError("tool handler received a non-tool node")
	}
	if strings.TrimSpace(tool.ToolCommand) == "" {
		return harness.Outcome{}, terminalError("no tool_command on " + tool.ID)
	}
	if scope.Stop != nil && scope.Stop.IsSet() {
		return harness.Outcome{}, interruptedError("tool command stopped by operator")
	}

	timeout, timeoutErr := toolTimeout(tool)
	if timeoutErr != nil {
		return harness.Outcome{}, terminalError(timeoutErr.Error())
	}
	logPath := filepath.Join(scope.StageDir, "tool.log")
	logFile, err := os.OpenFile(logPath, os.O_CREATE|os.O_TRUNC|os.O_WRONLY, 0o644)
	if err != nil {
		return harness.Outcome{}, terminalError(fmt.Sprintf("open tool log: %v", err))
	}

	ctx, cancel := context.WithCancelCause(context.Background())
	commandDone := make(chan struct{})
	if scope.Stop != nil {
		go func() {
			select {
			case <-scope.Stop.done:
				cancel(errToolStopped)
			case <-commandDone:
			}
		}()
	}
	var timer *time.Timer
	if tool.Timeout.Present {
		timer = time.AfterFunc(timeout, func() { cancel(errToolTimedOut) })
	}

	command := exec.CommandContext(ctx, "/bin/sh", "-c", tool.ToolCommand)
	command.Dir = scope.Workdir
	command.Stdout = logFile
	command.Stderr = logFile
	command.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
	command.Cancel = func() error {
		if command.Process == nil {
			return os.ErrProcessDone
		}
		err := syscall.Kill(-command.Process.Pid, syscall.SIGKILL)
		if errors.Is(err, syscall.ESRCH) {
			return os.ErrProcessDone
		}
		return err
	}
	runErr := command.Run()
	close(commandDone)
	if timer != nil {
		timer.Stop()
	}
	cause := context.Cause(ctx)
	cancel(nil)
	closeErr := logFile.Close()

	switch {
	case errors.Is(cause, errToolStopped):
		return harness.Outcome{}, interruptedError("tool command stopped by operator")
	case errors.Is(cause, errToolTimedOut):
		return harness.Outcome{}, interruptedError("tool command timed out")
	case closeErr != nil:
		return harness.Outcome{}, terminalError(fmt.Sprintf("close tool log: %v", closeErr))
	}

	exitCode := 0
	if runErr != nil {
		var exitError *exec.ExitError
		if !errors.As(runErr, &exitError) {
			return harness.Outcome{}, terminalError(fmt.Sprintf("run tool command: %v", runErr))
		}
		exitCode = exitError.ExitCode()
	}

	route, routeErr := toolRoute(tool, exitCode)
	if routeErr != nil {
		return harness.Outcome{}, routeErr
	}
	if !offeredTarget(offered, route) {
		return harness.Outcome{}, terminalError(fmt.Sprintf("exit-code route %s has exhausted its visit budget", route))
	}
	tail, err := toolLogTail(logPath)
	if err != nil {
		return harness.Outcome{}, terminalError(fmt.Sprintf("read tool log: %v", err))
	}
	return harness.Outcome{
		Next:  route,
		Notes: fmt.Sprintf("exit %d: %s", exitCode, tail),
	}, nil
}

func toolTimeout(node *graph.ToolNode) (time.Duration, error) {
	if !node.Timeout.Present {
		return 0, nil
	}
	timeout, err := node.Timeout.Value.Parse()
	if err != nil {
		return 0, fmt.Errorf("parse tool timeout: %w", err)
	}
	return timeout, nil
}

func toolRoute(node *graph.ToolNode, exitCode int) (string, *harness.Error) {
	if len(node.Edges) < 1 || len(node.Edges) > 2 {
		return "", terminalError("invalid tool routing on " + node.ID)
	}
	if exitCode != 0 {
		if node.OnFail == "" {
			return "", terminalError(fmt.Sprintf("%s exited %d", node.ToolCommand, exitCode))
		}
		return node.OnFail, nil
	}
	if len(node.Edges) == 1 {
		return node.Edges[0].To, nil
	}
	for _, edge := range node.Edges {
		if edge.To != node.OnFail {
			return edge.To, nil
		}
	}
	return "", terminalError("invalid tool success route on " + node.ID)
}

func offeredTarget(offered []graph.Edge, target string) bool {
	for _, edge := range offered {
		if edge.To == target {
			return true
		}
	}
	return false
}

func toolLogTail(path string) (string, error) {
	contents, err := os.ReadFile(path)
	if err != nil {
		return "", err
	}
	const maxTailRunes = 200
	tail := []rune(strings.TrimSpace(string(contents)))
	if len(tail) > maxTailRunes {
		tail = tail[len(tail)-maxTailRunes:]
	}
	return string(tail), nil
}

// Package graph defines and parses Tractor pipeline documents.
package graph

import (
	"encoding/json"
	"fmt"
	"strconv"
	"strings"
	"time"

	jsonschema "github.com/tylergannon/go-gen-jsonschema"
)

//go:generate go tool gen-jsonschema gen --pretty --validate
//go:generate go run ./internal/schemafix

// Graph is a complete pipeline definition.
type Graph struct {
	// Name is the pipeline's display name.
	Name string `json:"name,omitzero"`

	// Goal is the pipeline objective exposed to prompt expansion.
	Goal string `json:"goal,omitzero"`

	// Defaults contains file-level defaults for node fields.
	Defaults Defaults `json:"defaults,omitzero"`

	// Nodes is the graph. Each node carries its outgoing edges.
	Nodes []Node `json:"nodes"`
}

// Defaults contains the six fields that may be inherited by nodes.
type Defaults struct {
	MaxRetries      jsonschema.Optional[int]      `json:"max_retries,omitzero"`
	Fidelity        jsonschema.Optional[string]   `json:"fidelity,omitzero"`
	Timeout         jsonschema.Optional[Duration] `json:"timeout,omitzero"`
	LLMModel        jsonschema.Optional[string]   `json:"llm_model,omitzero"`
	LLMProvider     jsonschema.Optional[string]   `json:"llm_provider,omitzero"`
	ReasoningEffort jsonschema.Optional[string]   `json:"reasoning_effort,omitzero"`
}

// Duration is an integer followed by ms, s, m, h, or d.
type Duration string

// Parse converts d to a time.Duration. Days are fixed 24-hour periods.
func (d Duration) Parse() (time.Duration, error) {
	s := string(d)
	var number string
	switch {
	case strings.HasSuffix(s, "ms"):
		number = strings.TrimSuffix(s, "ms")
	case len(s) > 0 && strings.ContainsRune("smhd", rune(s[len(s)-1])):
		number = s[:len(s)-1]
	default:
		return 0, fmt.Errorf("parse duration %q: expected integer followed by ms, s, m, h, or d", s)
	}
	if number == "" {
		return 0, fmt.Errorf("parse duration %q: expected integer followed by ms, s, m, h, or d", s)
	}
	for _, digit := range number {
		if digit < '0' || digit > '9' {
			return 0, fmt.Errorf("parse duration %q: expected integer followed by ms, s, m, h, or d", s)
		}
	}
	if strings.HasSuffix(s, "d") {
		days, err := strconv.ParseInt(number, 10, 64)
		if err != nil {
			return 0, fmt.Errorf("parse duration %q: %w", s, err)
		}
		return time.Duration(days) * 24 * time.Hour, nil
	}
	parsed, err := time.ParseDuration(s)
	if err != nil {
		return 0, fmt.Errorf("parse duration %q: %w", s, err)
	}
	return parsed, nil
}

// Edge is an outgoing transition owned by its origin node.
type Edge struct {
	To        string `json:"to"`
	Condition string `json:"condition,omitzero"`
}

// Node is a pipeline stage.
type Node interface {
	isNode()
	Base() *NodeBase
	NodeType() string
}

// NodeBase contains fields admitted on every node type.
type NodeBase struct {
	ID        string                      `json:"id"`
	Label     jsonschema.Optional[string] `json:"label,omitzero"`
	Edges     []Edge                      `json:"edges,omitzero"`
	MaxVisits jsonschema.Optional[int]    `json:"max_visits,omitzero"`
}

// DisplayLabel returns the configured label or the node ID.
func (n *NodeBase) DisplayLabel() string {
	if n.Label.Present {
		return n.Label.Value
	}
	return n.ID
}

// StartNode is the pipeline entry point.
type StartNode struct{ NodeBase }

func (*StartNode) isNode()           {}
func (n *StartNode) Base() *NodeBase { return &n.NodeBase }
func (*StartNode) NodeType() string  { return "start" }

// ExitNode is the pipeline terminal node.
type ExitNode struct{ NodeBase }

func (*ExitNode) isNode()           {}
func (n *ExitNode) Base() *NodeBase { return &n.NodeBase }
func (*ExitNode) NodeType() string  { return "exit" }

// CodergenNode runs an LLM task.
type CodergenNode struct {
	NodeBase
	LLMNodeFields
}

func (*CodergenNode) isNode()           {}
func (n *CodergenNode) Base() *NodeBase { return &n.NodeBase }
func (*CodergenNode) NodeType() string  { return "codergen" }

// FanInNode evaluates parallel branch evidence with an LLM turn.
type FanInNode struct {
	NodeBase
	LLMNodeFields
}

func (*FanInNode) isNode()           {}
func (n *FanInNode) Base() *NodeBase { return &n.NodeBase }
func (*FanInNode) NodeType() string  { return "parallel.fan_in" }

// LLMNodeFields are shared by codergen and parallel fan-in nodes.
type LLMNodeFields struct {
	Prompt          jsonschema.Optional[string]   `json:"prompt,omitzero"`
	MaxRetries      jsonschema.Optional[int]      `json:"max_retries,omitzero"`
	Fidelity        jsonschema.Optional[string]   `json:"fidelity,omitzero"`
	ThreadID        jsonschema.Optional[string]   `json:"thread_id,omitzero"`
	Timeout         jsonschema.Optional[Duration] `json:"timeout,omitzero"`
	LLMModel        jsonschema.Optional[string]   `json:"llm_model,omitzero"`
	LLMProvider     jsonschema.Optional[string]   `json:"llm_provider,omitzero"`
	ReasoningEffort jsonschema.Optional[string]   `json:"reasoning_effort,omitzero"`
}

// PromptValue returns a non-empty prompt or falls back to label.
func (n *LLMNodeFields) PromptValue(label string) string {
	if n.Prompt.Present && n.Prompt.Value != "" {
		return n.Prompt.Value
	}
	return label
}

// ToolNode executes one shell command.
type ToolNode struct {
	NodeBase
	ToolCommand string                        `json:"tool_command"`
	OnFail      string                        `json:"on_fail,omitzero"`
	Timeout     jsonschema.Optional[Duration] `json:"timeout,omitzero"`
}

func (*ToolNode) isNode()           {}
func (n *ToolNode) Base() *NodeBase { return &n.NodeBase }
func (*ToolNode) NodeType() string  { return "tool" }

// ParallelNode concurrently walks each outgoing branch.
type ParallelNode struct {
	NodeBase
	MaxParallel jsonschema.Optional[int] `json:"max_parallel,omitzero"`
}

func (*ParallelNode) isNode()           {}
func (n *ParallelNode) Base() *NodeBase { return &n.NodeBase }
func (*ParallelNode) NodeType() string  { return "parallel" }

// CustomNode is the generic shape for a registered custom handler type.
type CustomNode struct {
	NodeBase
	Type       string                   `json:"type"`
	MaxRetries jsonschema.Optional[int] `json:"max_retries,omitzero"`
	Custom     OpaqueObject             `json:"custom,omitzero"`
}

func (*CustomNode) isNode()            {}
func (n *CustomNode) Base() *NodeBase  { return &n.NodeBase }
func (n *CustomNode) NodeType() string { return n.Type }

// OpaqueObject carries custom-handler configuration without interpretation.
// Its generated placeholder schema is opened by the deterministic schema
// normalization step because go-gen-jsonschema intentionally has no map type.
type OpaqueObject struct {
	value map[string]any
}

// Values returns the opaque object's decoded members.
func (o OpaqueObject) Values() map[string]any { return o.value }

func (o *OpaqueObject) UnmarshalJSON(data []byte) error {
	var value map[string]any
	if err := json.Unmarshal(data, &value); err != nil {
		return err
	}
	o.value = value
	return nil
}

func (o OpaqueObject) MarshalJSON() ([]byte, error) {
	if o.value == nil {
		return []byte("{}"), nil
	}
	return json.Marshal(o.value)
}

// MaxParallelValue returns the explicit maximum or the system default.
func (n *ParallelNode) MaxParallelValue() int {
	if n.MaxParallel.Present {
		return n.MaxParallel.Value
	}
	return 4
}

// ThreadKey returns the explicit thread ID or the node ID.
func (n *LLMNodeFields) ThreadKey(nodeID string) string {
	if n.ThreadID.Present {
		return n.ThreadID.Value
	}
	return nodeID
}

// FidelityValue returns the resolved fidelity or its system default.
func (n *LLMNodeFields) FidelityValue() string {
	if n.Fidelity.Present {
		return n.Fidelity.Value
	}
	return "compacted"
}

package graph

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"

	jsonschema "github.com/tylergannon/go-gen-jsonschema"
)

// Parse validates and decodes one pipeline document, then applies file-level
// defaults to the node types that admit each field.
func Parse(data []byte) (*Graph, error) {
	if err := preflight(data); err != nil {
		return nil, fmt.Errorf("parse pipeline: %w", err)
	}
	if err := (Graph{}).ValidateJSON(data); err != nil {
		return nil, fmt.Errorf("parse pipeline: %w", err)
	}

	var graph Graph
	if err := json.Unmarshal(data, &graph); err != nil {
		return nil, fmt.Errorf("parse pipeline: %w", err)
	}
	seen := make(map[string]struct{}, len(graph.Nodes))
	for _, node := range graph.Nodes {
		id := node.Base().ID
		if _, exists := seen[id]; exists {
			return nil, fmt.Errorf("parse pipeline: duplicate node ID %q", id)
		}
		seen[id] = struct{}{}
		if node.Base().Edges == nil {
			node.Base().Edges = []Edge{}
		}
	}
	graph.applyDefaults()
	return &graph, nil
}

// NodeByID returns the node with id, if present.
func (g *Graph) NodeByID(id string) (Node, bool) {
	for _, node := range g.Nodes {
		if node.Base().ID == id {
			return node, true
		}
	}
	return nil, false
}

func (g *Graph) applyDefaults() {
	for _, node := range g.Nodes {
		switch current := node.(type) {
		case *CodergenNode:
			inheritLLM(&current.LLMNodeFields, g.Defaults)
		case *FanInNode:
			inheritLLM(&current.LLMNodeFields, g.Defaults)
		case *ToolNode:
			inherit(&current.Timeout, g.Defaults.Timeout)
		case *CustomNode:
			inherit(&current.MaxRetries, g.Defaults.MaxRetries)
			if current.Custom.value == nil {
				current.Custom.value = map[string]any{}
			}
		}
	}
}

func inheritLLM(fields *LLMNodeFields, defaults Defaults) {
	inherit(&fields.MaxRetries, defaults.MaxRetries)
	inherit(&fields.Fidelity, defaults.Fidelity)
	inherit(&fields.Timeout, defaults.Timeout)
	inherit(&fields.LLMModel, defaults.LLMModel)
	inherit(&fields.LLMProvider, defaults.LLMProvider)
	inherit(&fields.ReasoningEffort, defaults.ReasoningEffort)
}

func inherit[T any](destination *jsonschema.Optional[T], source jsonschema.Optional[T]) {
	if !destination.Present && source.Present {
		*destination = source
	}
}

func preflight(data []byte) error {
	decoder := json.NewDecoder(bytes.NewReader(data))
	decoder.UseNumber()
	if err := scanValue(decoder); err != nil {
		return err
	}
	if _, err := decoder.Token(); !errors.Is(err, io.EOF) {
		if err == nil {
			return errors.New("more than one JSON value")
		}
		return err
	}
	return nil
}

func scanValue(decoder *json.Decoder) error {
	token, err := decoder.Token()
	if err != nil {
		return err
	}
	if token == nil {
		return errors.New("null is not allowed")
	}
	delim, ok := token.(json.Delim)
	if !ok {
		return nil
	}

	switch delim {
	case '{':
		members := map[string]struct{}{}
		for decoder.More() {
			nameToken, err := decoder.Token()
			if err != nil {
				return err
			}
			name, ok := nameToken.(string)
			if !ok {
				return errors.New("object member name is not a string")
			}
			if _, duplicate := members[name]; duplicate {
				return fmt.Errorf("duplicate object member %q", name)
			}
			members[name] = struct{}{}
			if err := scanValue(decoder); err != nil {
				return err
			}
		}
	case '[':
		for decoder.More() {
			if err := scanValue(decoder); err != nil {
				return err
			}
		}
	default:
		return fmt.Errorf("unexpected JSON delimiter %q", delim)
	}
	_, err = decoder.Token()
	return err
}

package harness

import (
	"encoding/json"
	"fmt"
	"maps"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"sync"
	"time"
)

const noneThreadPrefix = "\x00none:"

// DefaultProviderRoutes returns the standard provider-to-harness routing.
func DefaultProviderRoutes() map[string]string {
	return map[string]string{
		"anthropic": "claude",
		"openai":    "codex",
	}
}

// HarnessBackend routes codergen turns to harness adapters and owns the
// logical bindings, live controls, and run log for one pipeline run.
type HarnessBackend struct {
	logsRoot string
	adapters map[string]HarnessAdapter
	routes   map[string]string

	mu           sync.Mutex
	threads      map[string]ThreadBinding
	bindingLocks map[string]*sync.Mutex
	live         map[uint64]liveTurn
	nextLiveID   uint64

	nextSeq              uint64
	currentPinnedToIndex bool
}

type liveTurn struct {
	binding ThreadBinding
}

// NewHarnessBackend constructs a backend for one run. A nil routes map uses
// DefaultProviderRoutes. Restored bindings are copied into the backend.
func NewHarnessBackend(
	logsRoot string,
	adapters map[string]HarnessAdapter,
	routes map[string]string,
	bindings map[string]ThreadBinding,
) (*HarnessBackend, *Error) {
	if strings.TrimSpace(logsRoot) == "" {
		return nil, terminalError("logs root must not be empty")
	}
	if routes == nil {
		routes = DefaultProviderRoutes()
	}

	backend := &HarnessBackend{
		logsRoot:     logsRoot,
		adapters:     copyAdapters(adapters),
		routes:       copyStrings(routes),
		threads:      make(map[string]ThreadBinding, len(bindings)),
		bindingLocks: make(map[string]*sync.Mutex),
		live:         make(map[uint64]liveTurn),
	}
	for key, binding := range bindings {
		if strings.TrimSpace(key) == "" || !validBinding(binding) {
			return nil, terminalError(fmt.Sprintf("invalid restored thread binding %q", key))
		}
		if backend.adapters[binding.Harness] == nil {
			return nil, terminalError(fmt.Sprintf("restored thread %q uses unconfigured harness %q", key, binding.Harness))
		}
		backend.threads[key] = binding
	}
	eventsRoot := filepath.Join(logsRoot, "events")
	if err := os.MkdirAll(eventsRoot, 0o755); err != nil {
		return nil, terminalError(fmt.Sprintf("create run log directory: %v", err))
	}
	nextSeq, err := recoverEventSequence(eventsRoot)
	if err != nil {
		return nil, terminalError(fmt.Sprintf("recover run log sequence: %v", err))
	}
	backend.nextSeq = nextSeq
	return backend, nil
}

// Run executes one fully resolved codergen turn.
func (b *HarnessBackend) Run(turn CodergenTurn) (Outcome, *Error) {
	if err := ValidateCodergenTurn(turn); err != nil {
		return Outcome{}, err
	}
	validator, validationErr := NewResultValidator(turn.OutputSchema)
	if validationErr != nil {
		return Outcome{}, validationErr
	}
	harnessName, adapter, err := b.selectAdapter(turn.Provider)
	if err != nil {
		return Outcome{}, err
	}

	key := turn.ThreadKey
	if turn.Fidelity == FidelityNone {
		key = noneThreadPrefix + turn.NodeID
	}
	binding, err := b.prepareBinding(key, harnessName, adapter, turn)
	if err != nil {
		return Outcome{}, err
	}

	turnLog, liveID, err := b.startTurnLog(turn.NodeID, binding)
	if err != nil {
		return Outcome{}, err
	}
	result, adapterErr := adapter.RunTurn(RunTurnInput{
		SessionID:       binding.SessionID,
		Model:           turn.Model,
		ReasoningEffort: turn.ReasoningEffort,
		OutputSchema:    turn.OutputSchema,
		Workdir:         turn.Workdir,
		Parts:           turn.Parts,
		Timeout:         turn.Timeout,
	}, turnLog.writeEvent)
	logErr := b.finishTurnLog(liveID, turnLog)

	if adapterErr != nil {
		return Outcome{}, adapterErr
	}
	if logErr != nil {
		return Outcome{}, logErr
	}
	rawResult, marshalErr := json.Marshal(result)
	if marshalErr != nil {
		return Outcome{}, terminalError(fmt.Sprintf("encode harness result: %v", marshalErr))
	}
	validated, resultErr := validator.Validate(rawResult)
	if resultErr != nil {
		return Outcome{}, resultErr
	}
	return decodeOutcome(validated)
}

func (b *HarnessBackend) selectAdapter(provider string) (string, HarnessAdapter, *Error) {
	harnessName, ok := b.routes[provider]
	if !ok || strings.TrimSpace(harnessName) == "" {
		return "", nil, terminalError(fmt.Sprintf("no harness route for provider %q", provider))
	}
	adapter := b.adapters[harnessName]
	if adapter == nil {
		return "", nil, terminalError(fmt.Sprintf("harness %q is not configured", harnessName))
	}
	return harnessName, adapter, nil
}

func (b *HarnessBackend) prepareBinding(
	key string,
	harnessName string,
	adapter HarnessAdapter,
	turn CodergenTurn,
) (ThreadBinding, *Error) {
	lock := b.bindingLock(key)
	lock.Lock()
	defer lock.Unlock()

	b.mu.Lock()
	binding, exists := b.threads[key]
	b.mu.Unlock()
	if exists && turn.Fidelity != FidelityNone {
		if binding.Harness != harnessName {
			return ThreadBinding{}, terminalError("logical thread cannot change harness")
		}
		if binding.Workdir == turn.Workdir {
			if turn.Fidelity == FidelityCompacted {
				if err := adapter.Compact(binding.SessionID, turn.Workdir); err != nil {
					return ThreadBinding{}, err
				}
			}
			return binding, nil
		}
	}

	sessionID, err := adapter.CreateSession(turn.Model, turn.Workdir)
	if err != nil {
		return ThreadBinding{}, err
	}
	if strings.TrimSpace(sessionID) == "" {
		return ThreadBinding{}, terminalError("harness returned an empty session ID")
	}
	binding = ThreadBinding{Harness: harnessName, SessionID: sessionID, Workdir: turn.Workdir}
	b.mu.Lock()
	b.threads[key] = binding
	b.mu.Unlock()
	return binding, nil
}

func (b *HarnessBackend) bindingLock(key string) *sync.Mutex {
	b.mu.Lock()
	defer b.mu.Unlock()
	lock := b.bindingLocks[key]
	if lock == nil {
		lock = &sync.Mutex{}
		b.bindingLocks[key] = lock
	}
	return lock
}

// Steer sends a best-effort instruction when exactly one turn is live.
func (b *HarnessBackend) Steer(parts []ContentPart) SteerStatus {
	b.mu.Lock()
	if len(b.live) == 0 {
		b.mu.Unlock()
		return SteerNotActive
	}
	if len(b.live) != 1 {
		b.mu.Unlock()
		return SteerAmbiguousTarget
	}
	var target ThreadBinding
	for _, turn := range b.live {
		target = turn.binding
	}
	adapter := b.adapters[target.Harness]
	b.mu.Unlock()

	adapter.Steer(target.SessionID, parts)
	return SteerAccepted
}

// InterruptAll requests interruption of every live turn.
func (b *HarnessBackend) InterruptAll() {
	b.mu.Lock()
	targets := make([]ThreadBinding, 0, len(b.live))
	for _, turn := range b.live {
		targets = append(targets, turn.binding)
	}
	b.mu.Unlock()

	for _, target := range targets {
		b.adapters[target.Harness].Interrupt(target.SessionID)
	}
}

// Bindings returns a checkpoint-safe snapshot of all logical bindings.
func (b *HarnessBackend) Bindings() map[string]ThreadBinding {
	b.mu.Lock()
	defer b.mu.Unlock()
	bindings := make(map[string]ThreadBinding, len(b.threads))
	maps.Copy(bindings, b.threads)
	return bindings
}

type turnLog struct {
	file   *os.File
	nodeID string
	mu     sync.Mutex
	err    error
}

func (l *turnLog) writeEvent(event Event) {
	l.mu.Lock()
	defer l.mu.Unlock()
	if l.err != nil {
		return
	}
	stamped := make(Event, len(event)+2)
	maps.Copy(stamped, event)
	stamped["node_id"] = l.nodeID
	stamped["ts"] = time.Now().UTC().Format(time.RFC3339Nano)
	l.err = json.NewEncoder(l.file).Encode(stamped)
}

func (l *turnLog) close() error {
	l.mu.Lock()
	defer l.mu.Unlock()
	if err := l.file.Close(); l.err == nil {
		l.err = err
	}
	return l.err
}

func (b *HarnessBackend) startTurnLog(nodeID string, binding ThreadBinding) (*turnLog, uint64, *Error) {
	b.mu.Lock()
	defer b.mu.Unlock()
	b.nextSeq++
	seq := b.nextSeq
	name := fmt.Sprintf("%06d-%s.jsonl", seq, nodeID)
	relativePath := filepath.Join("events", name)
	absolutePath := filepath.Join(b.logsRoot, relativePath)
	file, err := os.OpenFile(absolutePath, os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0o644)
	if err != nil {
		return nil, 0, terminalError(fmt.Sprintf("create run log segment: %v", err))
	}
	entry := struct {
		Seq    uint64 `json:"seq"`
		NodeID string `json:"node_id"`
		Path   string `json:"path"`
		TS     string `json:"ts"`
	}{Seq: seq, NodeID: nodeID, Path: relativePath, TS: time.Now().UTC().Format(time.RFC3339Nano)}
	if err := appendJSONLine(filepath.Join(b.logsRoot, "events", "index.jsonl"), entry); err != nil {
		_ = file.Close()
		_ = os.Remove(absolutePath)
		return nil, 0, terminalError(fmt.Sprintf("append run log index: %v", err))
	}

	pinnedToIndex := b.currentPinnedToIndex || len(b.live) > 0
	currentTarget := relativePath
	if pinnedToIndex {
		currentTarget = filepath.Join("events", "index.jsonl")
	}
	if err := b.swapCurrent(currentTarget); err != nil {
		_ = file.Close()
		return nil, 0, terminalError(fmt.Sprintf("update current run log: %v", err))
	}
	b.nextLiveID++
	liveID := b.nextLiveID
	b.live[liveID] = liveTurn{binding: binding}
	b.currentPinnedToIndex = pinnedToIndex
	return &turnLog{file: file, nodeID: nodeID}, liveID, nil
}

func (b *HarnessBackend) finishTurnLog(liveID uint64, log *turnLog) *Error {
	closeErr := log.close()

	b.mu.Lock()
	defer b.mu.Unlock()
	delete(b.live, liveID)
	if len(b.live) == 0 {
		b.currentPinnedToIndex = false
	}
	if closeErr != nil {
		return terminalError(fmt.Sprintf("write run log segment: %v", closeErr))
	}
	return nil
}

func recoverEventSequence(eventsRoot string) (uint64, error) {
	entries, err := os.ReadDir(eventsRoot)
	if err != nil {
		return 0, err
	}
	var highest uint64
	for _, entry := range entries {
		if entry.IsDir() {
			continue
		}
		name := entry.Name()
		dash := strings.IndexByte(name, '-')
		if dash <= 0 || !strings.HasSuffix(name, ".jsonl") {
			continue
		}
		sequence, parseErr := strconv.ParseUint(name[:dash], 10, 64)
		if parseErr == nil && sequence > highest {
			highest = sequence
		}
	}
	return highest, nil
}

func (b *HarnessBackend) swapCurrent(target string) error {
	current := filepath.Join(b.logsRoot, "current.jsonl")
	temporary := filepath.Join(b.logsRoot, ".current.jsonl.tmp")
	if err := os.Remove(temporary); err != nil && !os.IsNotExist(err) {
		return err
	}
	if err := os.Symlink(target, temporary); err != nil {
		return err
	}
	if err := os.Rename(temporary, current); err != nil {
		_ = os.Remove(temporary)
		return err
	}
	return nil
}

func appendJSONLine(path string, value any) error {
	file, err := os.OpenFile(path, os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0o644)
	if err != nil {
		return err
	}
	encodeErr := json.NewEncoder(file).Encode(value)
	closeErr := file.Close()
	if encodeErr != nil {
		return encodeErr
	}
	return closeErr
}

func decodeOutcome(result Result) (Outcome, *Error) {
	notes, ok := result["notes"].(string)
	if !ok {
		return Outcome{}, terminalError("harness result has no string notes field")
	}
	outcome := Outcome{Notes: notes}
	if next, exists := result["next"]; exists {
		value, ok := next.(string)
		if !ok {
			return Outcome{}, terminalError("harness result has a non-string next field")
		}
		outcome.Next = value
	}
	return outcome, nil
}

func copyAdapters(source map[string]HarnessAdapter) map[string]HarnessAdapter {
	out := make(map[string]HarnessAdapter, len(source))
	maps.Copy(out, source)
	return out
}

func copyStrings(source map[string]string) map[string]string {
	out := make(map[string]string, len(source))
	maps.Copy(out, source)
	return out
}

func validBinding(binding ThreadBinding) bool {
	return strings.TrimSpace(binding.Harness) != "" &&
		strings.TrimSpace(binding.SessionID) != "" &&
		strings.TrimSpace(binding.Workdir) != ""
}

// Package harness defines the provider-neutral contracts shared by coding
// agent harness adapters and their callers.
package harness

import (
	"encoding/json"
	"fmt"
	"strings"
	"time"
)

// ErrorCategory describes how the orchestration engine handles an operational
// failure.
type ErrorCategory string

const (
	ErrorRetryable   ErrorCategory = "retryable"
	ErrorTerminal    ErrorCategory = "terminal"
	ErrorInterrupted ErrorCategory = "interrupted"
)

// Valid reports whether c is one of the public error categories.
func (c ErrorCategory) Valid() bool {
	switch c {
	case ErrorRetryable, ErrorTerminal, ErrorInterrupted:
		return true
	default:
		return false
	}
}

// Error is an operational harness failure.
type Error struct {
	Category ErrorCategory `json:"category"`
	Message  string        `json:"message"`
}

func (e *Error) Error() string {
	if e == nil {
		return ""
	}
	return fmt.Sprintf("%s: %s", e.Category, e.Message)
}

// Valid reports whether the error is safe to expose through the public
// contract.
func (e *Error) Valid() bool {
	return e != nil && e.Category.Valid() && strings.TrimSpace(e.Message) != ""
}

// ContentPart is one ordered part of a user message. This version of the
// contract supports the mandatory text part defined by the specification.
type ContentPart struct {
	Type string `json:"type"`
	Text string `json:"text"`
}

const ContentPartText = "text"

// FidelityMode controls whether a logical thread is reused.
type FidelityMode string

const (
	FidelityNone      FidelityMode = "none"
	FidelityFull      FidelityMode = "full"
	FidelityCompacted FidelityMode = "compacted"
)

// CodergenTurn is the fully resolved input to a CodergenBackend.
type CodergenTurn struct {
	NodeID          string
	Parts           []ContentPart
	OutputSchema    json.RawMessage
	Model           string
	Provider        string
	ReasoningEffort string
	Fidelity        FidelityMode
	ThreadKey       string
	Workdir         string
	Timeout         time.Duration
}

// Outcome is the semantic result of a codergen turn.
type Outcome struct {
	Next  string `json:"next,omitempty"`
	Notes string `json:"notes"`
}

// SteerStatus reports whether a backend accepted a steering handoff.
type SteerStatus string

const (
	SteerAccepted        SteerStatus = "accepted"
	SteerNotActive       SteerStatus = "not_active"
	SteerAmbiguousTarget SteerStatus = "ambiguous_target"
)

// ThreadBinding identifies the native harness session bound to a logical
// thread.
type ThreadBinding struct {
	Harness   string `json:"harness"`
	SessionID string `json:"session_id"`
	Workdir   string `json:"workdir"`
}

// CodergenBackend executes resolved codergen turns.
type CodergenBackend interface {
	Run(CodergenTurn) (Outcome, *Error)
	Steer([]ContentPart) SteerStatus
	InterruptAll()
	Bindings() map[string]ThreadBinding
}

// RunTurnInput is the fully resolved input to one harness turn.
type RunTurnInput struct {
	SessionID       string
	Model           string
	ReasoningEffort string
	OutputSchema    json.RawMessage
	Workdir         string
	Parts           []ContentPart
	Timeout         time.Duration
}

// Result is a harness response that has passed the caller's exact schema.
type Result map[string]any

// Event is one complete, provider-neutral logical item emitted during a turn.
// The event type set is open, so the representation preserves unknown fields.
type Event map[string]any

// OnEvent receives complete events in turn order.
type OnEvent func(Event)

const (
	EventUser       = "user"
	EventAssistant  = "assistant"
	EventThinking   = "thinking"
	EventToolCall   = "tool_call"
	EventToolResult = "tool_result"
	EventUsage      = "usage"
)

// HarnessAdapter translates the neutral contract into one native coding-agent
// harness.
type HarnessAdapter interface {
	CreateSession(model, workdir string) (string, *Error)
	RunTurn(RunTurnInput, OnEvent) (Result, *Error)
	Steer(sessionID string, parts []ContentPart)
	Interrupt(sessionID string)
	Compact(sessionID, workdir string) *Error
}

package lint

import (
	"fmt"
	"slices"
	"strings"

	"github.com/tylergannon/tractor/graph"
)

func (a *analysis) startNode() []Diagnostic {
	count := 0
	for _, node := range a.graph.Nodes {
		if _, ok := node.(*graph.StartNode); ok {
			count++
		}
	}
	if count == 1 {
		return nil
	}
	return []Diagnostic{diagnostic("start_node", SeverityError,
		fmt.Sprintf("pipeline must have exactly one start node; found %d", count), "")}
}

func (a *analysis) startSingleOutgoing() []Diagnostic {
	var diagnostics []Diagnostic
	for _, node := range a.graph.Nodes {
		if _, ok := node.(*graph.StartNode); ok && len(node.Base().Edges) != 1 {
			diagnostics = append(diagnostics, diagnostic("start_single_outgoing", SeverityError,
				fmt.Sprintf("start node must have exactly one outgoing edge; found %d", len(node.Base().Edges)), node.Base().ID))
		}
	}
	return diagnostics
}

func (a *analysis) terminalNode() []Diagnostic {
	count := 0
	for _, node := range a.graph.Nodes {
		if _, ok := node.(*graph.ExitNode); ok {
			count++
		}
	}
	if count == 1 {
		return nil
	}
	return []Diagnostic{diagnostic("terminal_node", SeverityError,
		fmt.Sprintf("pipeline must have exactly one exit node; found %d", count), "")}
}

func (a *analysis) reachability() []Diagnostic {
	startID := ""
	count := 0
	for _, node := range a.graph.Nodes {
		if _, ok := node.(*graph.StartNode); ok {
			startID = node.Base().ID
			count++
		}
	}
	if count != 1 {
		return nil
	}
	reachable := map[string]struct{}{startID: {}}
	queue := []string{startID}
	for len(queue) > 0 {
		from := queue[0]
		queue = queue[1:]
		for _, edge := range a.out[from] {
			if _, exists := a.byID[edge.edge.To]; !exists {
				continue
			}
			if _, seen := reachable[edge.edge.To]; seen {
				continue
			}
			reachable[edge.edge.To] = struct{}{}
			queue = append(queue, edge.edge.To)
		}
	}
	var diagnostics []Diagnostic
	for _, node := range a.graph.Nodes {
		if _, exists := reachable[node.Base().ID]; !exists {
			diagnostics = append(diagnostics, diagnostic("reachability", SeverityError,
				"node is unreachable from start", node.Base().ID))
		}
	}
	return diagnostics
}

func (a *analysis) edgeTargetExists() []Diagnostic {
	var diagnostics []Diagnostic
	for _, node := range a.graph.Nodes {
		for _, edge := range node.Base().Edges {
			if _, exists := a.byID[edge.To]; !exists {
				diagnostics = append(diagnostics, edgeDiagnostic("edge_target_exists",
					fmt.Sprintf("edge target %q does not exist", edge.To), node.Base().ID, edge.To))
			}
		}
	}
	return diagnostics
}

func (a *analysis) startNoIncoming() []Diagnostic {
	var diagnostics []Diagnostic
	for _, node := range a.graph.Nodes {
		if _, ok := node.(*graph.StartNode); ok && len(a.in[node.Base().ID]) > 0 {
			diagnostics = append(diagnostics, diagnostic("start_no_incoming", SeverityError,
				"start node must have no incoming edges", node.Base().ID))
		}
	}
	return diagnostics
}

func (a *analysis) exitNoOutgoing() []Diagnostic {
	var diagnostics []Diagnostic
	for _, node := range a.graph.Nodes {
		if _, ok := node.(*graph.ExitNode); ok && len(node.Base().Edges) > 0 {
			diagnostics = append(diagnostics, diagnostic("exit_no_outgoing", SeverityError,
				"exit node must have no outgoing edges", node.Base().ID))
		}
	}
	return diagnostics
}

func (a *analysis) deadEnd() []Diagnostic {
	var diagnostics []Diagnostic
	for _, node := range a.graph.Nodes {
		if _, terminal := node.(*graph.ExitNode); !terminal && len(node.Base().Edges) == 0 {
			diagnostics = append(diagnostics, diagnostic("dead_end", SeverityError,
				"non-terminal node must have at least one outgoing edge", node.Base().ID))
		}
	}
	return diagnostics
}

func (a *analysis) toolRouting() []Diagnostic {
	var diagnostics []Diagnostic
	for _, node := range a.graph.Nodes {
		tool, ok := node.(*graph.ToolNode)
		if !ok {
			continue
		}
		count := len(tool.Edges)
		valid := count == 1 || count == 2
		if tool.OnFail != "" {
			found := false
			for _, edge := range tool.Edges {
				found = found || edge.To == tool.OnFail
			}
			valid = valid && found
		} else if count == 2 {
			valid = false
		}
		if !valid {
			diagnostics = append(diagnostics, diagnostic("tool_routing", SeverityError,
				"tool node must have one or two outgoing edges; two edges require on_fail naming an outgoing target", tool.ID))
		}
	}
	return diagnostics
}

func (a *analysis) parallelFanIn() []Diagnostic {
	var diagnostics []Diagnostic
	for _, block := range a.parallelBlocks() {
		if block.unresolved {
			continue
		}
		if !block.converged {
			diagnostics = append(diagnostics, diagnostic("parallel_fan_in", SeverityError,
				"every branch must converge on one fan-in without first reaching exit or a dead region", block.node.ID))
		}
	}
	return diagnostics
}

func (a *analysis) branchDisjoint() []Diagnostic {
	var diagnostics []Diagnostic
	for _, block := range a.parallelBlocks() {
		if !block.converged {
			continue
		}
		for i := range block.branches {
			for j := i + 1; j < len(block.branches); j++ {
				for _, id := range intersection(block.branches[i].nodes, block.branches[j].nodes) {
					diagnostics = append(diagnostics, diagnostic("branch_disjoint", SeverityError,
						fmt.Sprintf("node belongs to branches %q and %q", block.branches[i].root, block.branches[j].root), id))
				}
			}
		}
	}
	return diagnostics
}

func (a *analysis) noNestedParallel() []Diagnostic {
	var diagnostics []Diagnostic
	for _, block := range a.parallelBlocks() {
		if !block.converged {
			continue
		}
		for _, node := range a.graph.Nodes {
			if _, inside := block.union[node.Base().ID]; !inside {
				continue
			}
			if _, nested := node.(*graph.ParallelNode); nested {
				diagnostics = append(diagnostics, diagnostic("no_nested_parallel", SeverityError,
					fmt.Sprintf("parallel node is nested inside branches of %q", block.node.ID), node.Base().ID))
			}
		}
	}
	return diagnostics
}

func (a *analysis) fanInSingleParallel() []Diagnostic {
	owners := map[string][]string{}
	for _, block := range a.parallelBlocks() {
		if block.candidate != "" {
			owners[block.candidate] = append(owners[block.candidate], block.node.ID)
		}
	}
	var diagnostics []Diagnostic
	for _, node := range a.graph.Nodes {
		if _, ok := node.(*graph.FanInNode); !ok {
			continue
		}
		count := len(owners[node.Base().ID])
		if count != 1 {
			diagnostics = append(diagnostics, diagnostic("fan_in_single_parallel", SeverityError,
				fmt.Sprintf("fan-in must belong to exactly one parallel node; found %d", count), node.Base().ID))
		}
	}
	return diagnostics
}

func (a *analysis) parallelThreadDisjoint() []Diagnostic {
	var diagnostics []Diagnostic
	for _, block := range a.parallelBlocks() {
		if !block.converged || !block.disjoint {
			continue
		}
		keys := make([]map[string]string, len(block.branches))
		for i, branch := range block.branches {
			keys[i] = a.threadNodes(branch.nodes)
		}
		for i := range keys {
			for j := i + 1; j < len(keys); j++ {
				common := make([]string, 0)
				for key := range keys[i] {
					if _, exists := keys[j][key]; exists {
						common = append(common, key)
					}
				}
				slices.Sort(common)
				for _, key := range common {
					diagnostics = append(diagnostics, diagnostic("parallel_thread_disjoint", SeverityError,
						fmt.Sprintf("thread key %q is shared across concurrent branches by %q and %q", key, keys[i][key], keys[j][key]), keys[i][key]))
				}
			}
		}
	}
	return diagnostics
}

func (a *analysis) threadBranchBoundary() []Diagnostic {
	var diagnostics []Diagnostic
	for _, block := range a.parallelBlocks() {
		if !block.converged || !block.disjoint {
			continue
		}
		for _, branch := range block.branches {
			seenKeys := map[string]struct{}{}
			for _, inside := range a.graph.Nodes {
				if _, member := branch.nodes[inside.Base().ID]; !member {
					continue
				}
				key, reusable := a.reusableThread(inside)
				if !reusable {
					continue
				}
				if _, seen := seenKeys[key]; seen {
					continue
				}
				seenKeys[key] = struct{}{}
				for _, outside := range a.graph.Nodes {
					if _, member := branch.nodes[outside.Base().ID]; member {
						continue
					}
					outsideKey, outsideReusable := a.reusableThread(outside)
					if outsideReusable && outsideKey == key {
						diagnostics = append(diagnostics, diagnostic("thread_branch_boundary", SeverityError,
							fmt.Sprintf("thread key %q crosses the branch worktree boundary between %q and %q", key, inside.Base().ID, outside.Base().ID), inside.Base().ID))
						break
					}
				}
			}
		}
	}
	return diagnostics
}

func (a *analysis) fanInEntry() []Diagnostic {
	var diagnostics []Diagnostic
	for _, block := range a.parallelBlocks() {
		if !block.converged {
			continue
		}
		for _, incoming := range a.in[block.candidate] {
			if _, inside := block.union[incoming.from]; !inside {
				diagnostics = append(diagnostics, edgeDiagnostic("fan_in_entry",
					fmt.Sprintf("fan-in %q may only be entered from its branches", block.candidate), incoming.from, block.candidate))
			}
		}
	}
	return diagnostics
}

func (a *analysis) branchEntry() []Diagnostic {
	var diagnostics []Diagnostic
	for _, block := range a.parallelBlocks() {
		if !block.converged || !block.disjoint {
			continue
		}
		for _, branch := range block.branches {
			for _, node := range a.graph.Nodes {
				id := node.Base().ID
				if _, member := branch.nodes[id]; !member {
					continue
				}
				for _, incoming := range a.in[id] {
					_, inside := branch.nodes[incoming.from]
					fromParallel := id == branch.root && incoming.from == block.node.ID
					if !inside && !fromParallel {
						diagnostics = append(diagnostics, edgeDiagnostic("branch_entry",
							fmt.Sprintf("branch node %q may only be entered from its own branch", id), incoming.from, id))
					}
				}
			}
		}
	}
	return diagnostics
}

func (a *analysis) maxVisitsPositive() []Diagnostic {
	var diagnostics []Diagnostic
	for _, node := range a.graph.Nodes {
		value := node.Base().MaxVisits
		if value.Present && value.Value <= 0 {
			diagnostics = append(diagnostics, diagnostic("max_visits_positive", SeverityError,
				"max_visits must be positive", node.Base().ID))
		}
	}
	return diagnostics
}

func (a *analysis) maxParallelPositive() []Diagnostic {
	var diagnostics []Diagnostic
	for _, node := range a.graph.Nodes {
		parallel, ok := node.(*graph.ParallelNode)
		if ok && parallel.MaxParallel.Present && parallel.MaxParallel.Value <= 0 {
			diagnostics = append(diagnostics, diagnostic("max_parallel_positive", SeverityError,
				"max_parallel must be positive", parallel.ID))
		}
	}
	return diagnostics
}

func (a *analysis) maxRetriesNonnegative() []Diagnostic {
	var diagnostics []Diagnostic
	invalidDefault := a.graph.Defaults.MaxRetries.Present && a.graph.Defaults.MaxRetries.Value < 0
	if invalidDefault {
		diagnostics = append(diagnostics, diagnostic("max_retries_nonnegative", SeverityError,
			"defaults.max_retries must be nonnegative", ""))
	}
	for _, node := range a.graph.Nodes {
		value, present := maxRetries(node)
		if !present || value >= 0 {
			continue
		}
		if invalidDefault && value == a.graph.Defaults.MaxRetries.Value {
			continue
		}
		diagnostics = append(diagnostics, diagnostic("max_retries_nonnegative", SeverityError,
			"max_retries must be nonnegative", node.Base().ID))
	}
	return diagnostics
}

func (a *analysis) edgeConditionMissing() []Diagnostic {
	var diagnostics []Diagnostic
	for _, node := range a.graph.Nodes {
		_, codergen := node.(*graph.CodergenNode)
		_, fanIn := node.(*graph.FanInNode)
		if (!codergen && !fanIn) || len(node.Base().Edges) <= 1 {
			continue
		}
		for _, edge := range node.Base().Edges {
			if strings.TrimSpace(edge.Condition) == "" {
				diagnostics = append(diagnostics, edgeDiagnostic("edge_condition_missing",
					"choice edge condition must be non-empty", node.Base().ID, edge.To))
			}
		}
	}
	return diagnostics
}

func (a *analysis) typeKnown() []Diagnostic {
	var diagnostics []Diagnostic
	for _, node := range a.graph.Nodes {
		if _, known := a.opts.knownTypes[node.NodeType()]; !known {
			diagnostics = append(diagnostics, diagnostic("type_known", SeverityError,
				fmt.Sprintf("node type %q is not registered", node.NodeType()), node.Base().ID))
		}
	}
	return diagnostics
}

func (a *analysis) fidelityValid() []Diagnostic {
	var diagnostics []Diagnostic
	invalidDefault := false
	if a.graph.Defaults.Fidelity.Present {
		_, valid := a.opts.supportedFidelity[a.graph.Defaults.Fidelity.Value]
		invalidDefault = !valid
		if !valid {
			diagnostics = append(diagnostics, diagnostic("fidelity_valid", SeverityError,
				fmt.Sprintf("unsupported defaults.fidelity %q", a.graph.Defaults.Fidelity.Value), ""))
		}
	}
	for _, node := range a.graph.Nodes {
		fields, ok := llmFields(node)
		if !ok || !fields.Fidelity.Present {
			continue
		}
		if _, valid := a.opts.supportedFidelity[fields.Fidelity.Value]; valid {
			continue
		}
		if invalidDefault && fields.Fidelity.Value == a.graph.Defaults.Fidelity.Value {
			continue
		}
		diagnostics = append(diagnostics, diagnostic("fidelity_valid", SeverityError,
			fmt.Sprintf("unsupported fidelity %q", fields.Fidelity.Value), node.Base().ID))
	}
	return diagnostics
}

func (a *analysis) threadIDCollision() []Diagnostic {
	ids := make(map[string]struct{}, len(a.graph.Nodes))
	for _, node := range a.graph.Nodes {
		ids[node.Base().ID] = struct{}{}
	}
	var diagnostics []Diagnostic
	for _, node := range a.graph.Nodes {
		fields, ok := llmFields(node)
		if !ok || !fields.ThreadID.Present {
			continue
		}
		if _, collision := ids[fields.ThreadID.Value]; collision {
			diagnostics = append(diagnostics, diagnostic("thread_id_collision", SeverityError,
				fmt.Sprintf("explicit thread_id %q collides with a node ID", fields.ThreadID.Value), node.Base().ID))
		}
	}
	return diagnostics
}

func (a *analysis) threadHarnessConsistent() []Diagnostic {
	groups := map[string][]graph.Node{}
	var order []string
	for _, node := range a.graph.Nodes {
		key, reusable := a.reusableThread(node)
		if !reusable {
			continue
		}
		if _, exists := groups[key]; !exists {
			order = append(order, key)
		}
		groups[key] = append(groups[key], node)
	}
	var diagnostics []Diagnostic
	for _, key := range order {
		nodes := groups[key]
		if len(nodes) < 2 {
			continue
		}
		harnesses := map[string]struct{}{}
		resolutionFailed := false
		for _, node := range nodes {
			harness, err := a.threadHarness(node)
			if err != nil {
				diagnostics = append(diagnostics, diagnostic("thread_harness_consistent", SeverityError,
					fmt.Sprintf("cannot resolve harness for shared thread %q: %v", key, err), node.Base().ID))
				resolutionFailed = true
				break
			}
			harnesses[harness] = struct{}{}
		}
		if !resolutionFailed && len(harnesses) > 1 {
			diagnostics = append(diagnostics, diagnostic("thread_harness_consistent", SeverityError,
				fmt.Sprintf("nodes sharing thread key %q resolve to different harnesses", key), nodes[0].Base().ID))
		}
	}
	return diagnostics
}

func (a *analysis) fanInMaxVisits() []Diagnostic {
	var diagnostics []Diagnostic
	for _, node := range a.graph.Nodes {
		if _, fanIn := node.(*graph.FanInNode); fanIn && node.Base().MaxVisits.Present {
			diagnostics = append(diagnostics, diagnostic("fan_in_max_visits", SeverityWarning,
				"max_visits on fan-in does not bound the parallel loop", node.Base().ID))
		}
	}
	return diagnostics
}

func (a *analysis) branchRootMaxVisits() []Diagnostic {
	var diagnostics []Diagnostic
	for _, node := range a.graph.Nodes {
		parallel, ok := node.(*graph.ParallelNode)
		if !ok {
			continue
		}
		seen := map[string]struct{}{}
		for _, edge := range parallel.Edges {
			if _, duplicate := seen[edge.To]; duplicate {
				continue
			}
			seen[edge.To] = struct{}{}
			root, exists := a.byID[edge.To]
			if exists && root.Base().MaxVisits.Present {
				diagnostics = append(diagnostics, diagnostic("branch_root_max_visits", SeverityWarning,
					fmt.Sprintf("max_visits on branch root silently shrinks later fan-outs from %q", parallel.ID), root.Base().ID))
			}
		}
	}
	return diagnostics
}

func (a *analysis) promptOnLLMNodes() []Diagnostic {
	var diagnostics []Diagnostic
	for _, node := range a.graph.Nodes {
		codergen, ok := node.(*graph.CodergenNode)
		if ok && !codergen.Prompt.Present && !codergen.Label.Present {
			diagnostics = append(diagnostics, diagnostic("prompt_on_llm_nodes", SeverityWarning,
				"codergen node should have an authored prompt or label", codergen.ID))
		}
	}
	return diagnostics
}

func (a *analysis) threadNodes(nodes map[string]struct{}) map[string]string {
	keys := map[string]string{}
	for _, node := range a.graph.Nodes {
		if _, inside := nodes[node.Base().ID]; !inside {
			continue
		}
		if key, reusable := a.reusableThread(node); reusable {
			if _, exists := keys[key]; !exists {
				keys[key] = node.Base().ID
			}
		}
	}
	return keys
}

func maxRetries(node graph.Node) (int, bool) {
	switch node := node.(type) {
	case *graph.CodergenNode:
		return node.MaxRetries.Value, node.MaxRetries.Present
	case *graph.FanInNode:
		return node.MaxRetries.Value, node.MaxRetries.Present
	case *graph.CustomNode:
		return node.MaxRetries.Value, node.MaxRetries.Present
	default:
		return 0, false
	}
}

package main

import (
	"context"
	"fmt"
	"os"
	"os/signal"
	"path/filepath"
	"strings"
	"syscall"

	"github.com/spf13/cobra"
	"github.com/tylergannon/tractor/engine"
	"github.com/tylergannon/tractor/graph"
	"github.com/tylergannon/tractor/harness"
	"github.com/tylergannon/tractor/harness/claude"
	"github.com/tylergannon/tractor/harness/codex"
	"github.com/tylergannon/tractor/lint"
)

const (
	defaultModel           = "gpt-5.6-sol"
	defaultReasoningEffort = "high"
)

func newRootCommand() *cobra.Command {
	root := &cobra.Command{
		Use:               "tractor",
		Short:             "Run Tractor pipelines",
		SilenceErrors:     true,
		SilenceUsage:      true,
		CompletionOptions: cobra.CompletionOptions{DisableDefaultCmd: true},
	}
	root.AddCommand(newValidateCommand(), newRunCommand(), newPrintSchemaCommand())
	return root
}

func newValidateCommand() *cobra.Command {
	var inlineJSON string
	command := &cobra.Command{
		Use:   "validate [pipeline.json]",
		Short: "Parse and validate a pipeline",
		RunE: func(command *cobra.Command, args []string) error {
			pipeline, source, err := loadPipeline(args, inlineJSON, command.Flags().Changed("json"))
			if err != nil {
				return err
			}
			if err := validateAndReport(command, cliValidator(), *pipeline); err != nil {
				return err
			}
			_, err = fmt.Fprintf(command.OutOrStdout(), "valid %s\n", source)
			return err
		},
	}
	command.Flags().StringVar(&inlineJSON, "json", "", "pipeline JSON")
	return command
}

func newRunCommand() *cobra.Command {
	var inlineJSON string
	var workdir string
	var logsRoot string
	var resume bool
	command := &cobra.Command{
		Use:   "run [pipeline.json]",
		Short: "Run a pipeline",
		RunE: func(command *cobra.Command, args []string) error {
			pipeline, _, err := loadPipeline(args, inlineJSON, command.Flags().Changed("json"))
			if err != nil {
				return err
			}
			return runPipeline(command, *pipeline, workdir, logsRoot, resume)
		},
	}
	command.Flags().StringVar(&inlineJSON, "json", "", "pipeline JSON")
	command.Flags().StringVar(&workdir, "workdir", ".", "pipeline workspace")
	command.Flags().StringVar(&logsRoot, "logs", "", "run log directory")
	command.Flags().BoolVar(&resume, "resume", false, "resume from the logs checkpoint")
	return command
}

func newPrintSchemaCommand() *cobra.Command {
	return &cobra.Command{
		Use:   "print-schema",
		Short: "Print the pipeline JSON Schema",
		Args:  cobra.NoArgs,
		RunE: func(command *cobra.Command, _ []string) error {
			_, err := command.OutOrStdout().Write(graph.Graph{}.Schema())
			return err
		},
	}
}

func loadPipeline(args []string, inlineJSON string, inlineSet bool) (*graph.Graph, string, error) {
	if len(args) > 1 {
		return nil, "", fmt.Errorf("accepts exactly one pipeline source")
	}
	if inlineSet && len(args) == 1 {
		return nil, "", fmt.Errorf("pipeline file and --json are mutually exclusive")
	}
	if !inlineSet && len(args) == 0 {
		return nil, "", fmt.Errorf("pipeline source is required: provide a file or --json")
	}
	if inlineSet {
		pipeline, err := graph.Parse([]byte(inlineJSON))
		return pipeline, "--json", err
	}
	raw, err := os.ReadFile(args[0])
	if err != nil {
		return nil, "", fmt.Errorf("read pipeline %q: %w", args[0], err)
	}
	pipeline, err := graph.Parse(raw)
	return pipeline, args[0], err
}

func runPipeline(command *cobra.Command, pipeline graph.Graph, workdir, logsRoot string, resume bool) error {
	if strings.TrimSpace(logsRoot) == "" {
		return fmt.Errorf("--logs is required")
	}
	workdir, err := absoluteDirectory(workdir)
	if err != nil {
		return err
	}
	logsRoot, err = filepath.Abs(logsRoot)
	if err != nil {
		return fmt.Errorf("resolve logs directory: %w", err)
	}
	validator := cliValidator()
	if err := validateAndReport(command, validator, pipeline); err != nil {
		return err
	}

	var bindings map[string]harness.ThreadBinding
	if resume {
		checkpoint, err := engine.LoadCheckpoint(logsRoot)
		if err != nil {
			return err
		}
		bindings = checkpoint.Sessions
	}
	codexAdapter := codex.New()
	codexAdapter.SetStderr(command.ErrOrStderr())
	defer codexAdapter.Close()
	claudeAdapter := claude.New()
	claudeAdapter.SetStderr(command.ErrOrStderr())
	defer claudeAdapter.Close()
	backend, backendErr := harness.NewHarnessBackend(
		logsRoot,
		map[string]harness.HarnessAdapter{"codex": codexAdapter, "claude": claudeAdapter},
		harness.DefaultProviderRoutes(),
		bindings,
	)
	if backendErr != nil {
		return backendErr
	}

	registry := engine.NewRegistry()
	codergenConfig := engine.CodergenConfig{
		Backend:                backend,
		DefaultModel:           defaultModel,
		DefaultReasoningEffort: defaultReasoningEffort,
	}
	registry.Register("codergen", engine.NewCodergenHandler(codergenConfig))
	registry.Register("parallel.fan_in", engine.NewFanInHandler(codergenConfig))
	runnerConfig := engine.RunnerConfig{
		LogsRoot: logsRoot,
		Workdir:  workdir,
		Validate: func(candidate graph.Graph) error {
			_, err := validator.ValidateOrError(candidate)
			return err
		},
		Backend: backend,
	}
	var runner *engine.Runner
	if resume {
		runner, err = engine.ResumeRunner(pipeline, registry, runnerConfig)
	} else {
		runner, err = engine.NewRunner(pipeline, registry, runnerConfig)
	}
	if err != nil {
		return err
	}

	ctx, stopSignals := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stopSignals()
	done := make(chan struct{})
	defer close(done)
	go func() {
		select {
		case <-ctx.Done():
			runner.Stop()
		case <-done:
		}
	}()
	result, err := runner.Run()
	if err != nil {
		return err
	}
	if result.Status != engine.RunCompleted {
		return fmt.Errorf("pipeline failed: %s", result.FailureReason)
	}
	_, err = fmt.Fprintln(command.OutOrStdout(), result.Status)
	return err
}

func absoluteDirectory(path string) (string, error) {
	absolute, err := filepath.Abs(path)
	if err != nil {
		return "", fmt.Errorf("resolve workdir: %w", err)
	}
	info, err := os.Stat(absolute)
	if err != nil {
		return "", fmt.Errorf("inspect workdir: %w", err)
	}
	if !info.IsDir() {
		return "", fmt.Errorf("workdir %q is not a directory", absolute)
	}
	return absolute, nil
}

func cliValidator() *lint.Validator {
	return lint.New(lint.Options{ResolveHarness: resolveHarness})
}

func resolveHarness(provider, model string) (string, error) {
	if provider == "" {
		if model == "" {
			model = defaultModel
		}
		provider = engine.DetectProvider(model)
	}
	harnessName := harness.DefaultProviderRoutes()[provider]
	if harnessName == "" {
		return "", fmt.Errorf("no harness route for provider %q", provider)
	}
	return harnessName, nil
}

func validateAndReport(command *cobra.Command, validator *lint.Validator, pipeline graph.Graph) error {
	diagnostics := validator.Validate(pipeline)
	for _, diagnostic := range diagnostics {
		if diagnostic.Severity == lint.SeverityError {
			continue
		}
		if _, err := fmt.Fprintf(command.ErrOrStderr(), "%s %s: %s\n", diagnostic.Severity, diagnostic.Rule, diagnostic.Message); err != nil {
			return err
		}
	}
	if lint.HasErrors(diagnostics) {
		return &lint.ValidationError{Diagnostics: diagnostics}
	}
	return nil
}

package main

import (
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"os"
	"os/signal"
	"path/filepath"
	"strings"
	"time"

	"github.com/tylergannon/tractor/harness"
	"github.com/tylergannon/tractor/harness/claude"
	"github.com/tylergannon/tractor/harness/codex"
)

const (
	callerNone   = ""
	callerClaude = "claude"
	callerCodex  = "codex"
)

var outcomeSchema = json.RawMessage(`{
	"type":"object",
	"properties":{"next":{"type":"string"},"notes":{"type":"string"}},
	"required":["next","notes"],
	"additionalProperties":false
}`)

type options struct {
	provider        string
	model           string
	reasoningEffort string
	sessionID       string
	logsRoot        string
	timeout         time.Duration
}

type commandResult struct {
	Outcome   harness.Outcome `json:"outcome"`
	SessionID string          `json:"session_id"`
	LogsRoot  string          `json:"logs_root"`
}

func main() {
	if err := run(os.Args[1:]); err != nil {
		_, _ = fmt.Fprintln(os.Stderr, "agent:", err)
		os.Exit(1)
	}
}

func run(args []string) error {
	flags := flag.NewFlagSet("agent", flag.ContinueOnError)
	flags.SetOutput(os.Stderr)
	var values options
	flags.StringVar(&values.provider, "provider", "", "provider (standalone: openai or anthropic)")
	flags.StringVar(&values.model, "model", "", "model (standalone required)")
	flags.StringVar(&values.reasoningEffort, "reasoning-effort", "", "reasoning effort (standalone required)")
	flags.StringVar(&values.sessionID, "session", "", "existing native session ID")
	flags.StringVar(&values.logsRoot, "logs", "", "run log directory (default: a new temporary directory)")
	flags.DurationVar(&values.timeout, "timeout", 20*time.Minute, "turn timeout")
	if err := flags.Parse(args); err != nil {
		return err
	}
	positionals := flags.Args()
	if len(positionals) < 2 {
		return errors.New("usage: agent [flags] WORKDIR PROMPT")
	}
	selection, err := resolveSelection(detectCaller(os.Getenv), values)
	if err != nil {
		return err
	}
	workdir, err := filepath.Abs(positionals[0])
	if err != nil {
		return fmt.Errorf("resolve workdir: %w", err)
	}
	info, err := os.Stat(workdir)
	if err != nil {
		return fmt.Errorf("inspect workdir: %w", err)
	}
	if !info.IsDir() {
		return fmt.Errorf("workdir %q is not a directory", workdir)
	}
	if selection.logsRoot == "" {
		selection.logsRoot, err = os.MkdirTemp("", "tractor-agent-logs-")
		if err != nil {
			return fmt.Errorf("create logs directory: %w", err)
		}
	} else {
		selection.logsRoot, err = filepath.Abs(selection.logsRoot)
		if err != nil {
			return fmt.Errorf("resolve logs directory: %w", err)
		}
	}

	codexAdapter := codex.New()
	codexAdapter.SetStderr(os.Stderr)
	defer codexAdapter.Close()
	claudeAdapter := claude.New()
	claudeAdapter.SetStderr(os.Stderr)
	defer claudeAdapter.Close()
	harnessName, err := harnessForProvider(selection.provider)
	if err != nil {
		return err
	}
	bindings := map[string]harness.ThreadBinding(nil)
	if selection.sessionID != "" {
		bindings = map[string]harness.ThreadBinding{
			"agent": {Harness: harnessName, SessionID: selection.sessionID, Workdir: workdir},
		}
	}
	backend, backendErr := harness.NewHarnessBackend(
		selection.logsRoot,
		map[string]harness.HarnessAdapter{"codex": codexAdapter, "claude": claudeAdapter},
		map[string]string{"openai": "codex", "anthropic": "claude"},
		bindings,
	)
	if backendErr != nil {
		return backendErr
	}

	interrupts := make(chan os.Signal, 1)
	signal.Notify(interrupts, os.Interrupt)
	defer signal.Stop(interrupts)
	done := make(chan struct{})
	defer close(done)
	go func() {
		select {
		case <-interrupts:
			backend.InterruptAll()
		case <-done:
		}
	}()

	outcome, runErr := backend.Run(harness.CodergenTurn{
		NodeID:          "agent",
		Parts:           []harness.ContentPart{{Type: harness.ContentPartText, Text: strings.Join(positionals[1:], " ")}},
		OutputSchema:    outcomeSchema,
		Model:           selection.model,
		Provider:        selection.provider,
		ReasoningEffort: selection.reasoningEffort,
		Fidelity:        harness.FidelityFull,
		ThreadKey:       "agent",
		Workdir:         workdir,
		Timeout:         selection.timeout,
	})
	if runErr != nil {
		return runErr
	}
	binding := backend.Bindings()["agent"]
	return json.NewEncoder(os.Stdout).Encode(commandResult{
		Outcome:   outcome,
		SessionID: binding.SessionID,
		LogsRoot:  selection.logsRoot,
	})
}

func detectCaller(getenv func(string) string) string {
	if strings.TrimSpace(getenv("CLAUDE_CODE_SESSION_ID")) != "" {
		return callerClaude
	}
	if strings.TrimSpace(getenv("CODEX_THREAD_ID")) != "" {
		return callerCodex
	}
	return callerNone
}

func resolveSelection(caller string, values options) (options, error) {
	switch caller {
	case callerClaude:
		values.provider = "openai"
		values.model = "gpt-5.6-sol"
		values.reasoningEffort = "medium"
	case callerCodex:
		values.provider = "anthropic"
		values.model = "fable"
		values.reasoningEffort = "medium"
	case callerNone:
		if strings.TrimSpace(values.provider) == "" || strings.TrimSpace(values.model) == "" || strings.TrimSpace(values.reasoningEffort) == "" {
			return options{}, errors.New("standalone use requires --provider, --model, and --reasoning-effort")
		}
	default:
		return options{}, fmt.Errorf("unknown caller %q", caller)
	}
	if _, err := harnessForProvider(values.provider); err != nil {
		return options{}, err
	}
	if values.timeout < 0 {
		return options{}, errors.New("timeout must not be negative")
	}
	return values, nil
}

func harnessForProvider(provider string) (string, error) {
	switch provider {
	case "openai":
		return "codex", nil
	case "anthropic":
		return "claude", nil
	default:
		return "", fmt.Errorf("unsupported provider %q", provider)
	}
}

package harness

import (
	"fmt"
	"strings"
)

// ValidateCreateSessionInput validates the provider-neutral inputs available
// before a native session is created.
func ValidateCreateSessionInput(model, workdir string) *Error {
	if strings.TrimSpace(model) == "" {
		return terminalError("model must not be empty")
	}
	if strings.TrimSpace(workdir) == "" {
		return terminalError("workdir must not be empty")
	}
	return nil
}

// ValidateRunTurnInput validates a turn before native harness activity begins.
func ValidateRunTurnInput(input RunTurnInput, onEvent OnEvent) *Error {
	if strings.TrimSpace(input.SessionID) == "" {
		return terminalError("session ID must not be empty")
	}
	if err := ValidateCreateSessionInput(input.Model, input.Workdir); err != nil {
		return err
	}
	if strings.TrimSpace(input.ReasoningEffort) == "" {
		return terminalError("reasoning effort must not be empty")
	}
	if err := ValidateContentParts(input.Parts); err != nil {
		return err
	}
	if input.Timeout < 0 {
		return terminalError("timeout must not be negative")
	}
	if onEvent == nil {
		return terminalError("event callback must not be nil")
	}
	return nil
}

// ValidateSessionInput validates inputs for a session-scoped operation.
func ValidateSessionInput(sessionID, workdir string) *Error {
	if strings.TrimSpace(sessionID) == "" {
		return terminalError("session ID must not be empty")
	}
	if strings.TrimSpace(workdir) == "" {
		return terminalError("workdir must not be empty")
	}
	return nil
}

// ValidateContentParts enforces the non-empty ordered text-part contract.
func ValidateContentParts(parts []ContentPart) *Error {
	if len(parts) == 0 {
		return terminalError("content parts must not be empty")
	}
	for i, part := range parts {
		if part.Type != ContentPartText {
			return terminalError(fmt.Sprintf("content part %d has unsupported type %q", i, part.Type))
		}
	}
	return nil
}

// ValidateCodergenTurn validates a fully resolved backend turn.
func ValidateCodergenTurn(turn CodergenTurn) *Error {
	if strings.TrimSpace(turn.NodeID) == "" {
		return terminalError("node ID must not be empty")
	}
	if strings.TrimSpace(turn.Provider) == "" {
		return terminalError("provider must not be empty")
	}
	if err := ValidateCreateSessionInput(turn.Model, turn.Workdir); err != nil {
		return err
	}
	if strings.TrimSpace(turn.ReasoningEffort) == "" {
		return terminalError("reasoning effort must not be empty")
	}
	if err := ValidateContentParts(turn.Parts); err != nil {
		return err
	}
	if turn.Timeout < 0 {
		return terminalError("timeout must not be negative")
	}
	switch turn.Fidelity {
	case FidelityNone:
		if turn.ThreadKey != "" {
			return terminalError("thread key must be empty for none fidelity")
		}
	case FidelityFull, FidelityCompacted:
		if strings.TrimSpace(turn.ThreadKey) == "" {
			return terminalError("thread key must not be empty for reusable fidelity")
		}
	default:
		return terminalError(fmt.Sprintf("unsupported fidelity %q", turn.Fidelity))
	}
	return nil
}

func terminalError(message string) *Error {
	return &Error{Category: ErrorTerminal, Message: message}
}

package harness

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"

	jsonschema "github.com/santhosh-tekuri/jsonschema/v6"
)

const outputSchemaURL = "urn:tractor:harness:output-schema"

// ResultValidator validates native harness output against one caller-supplied
// JSON Schema.
type ResultValidator struct {
	schema *jsonschema.Schema
}

// NewResultValidator compiles the exact supplied schema and verifies that its
// root describes a JSON object.
func NewResultValidator(rawSchema json.RawMessage) (*ResultValidator, *Error) {
	document, err := decodeOneJSON(rawSchema)
	if err != nil {
		return nil, terminalError(fmt.Sprintf("invalid output schema: %v", err))
	}
	object, ok := document.(map[string]any)
	if !ok {
		return nil, terminalError("output schema must be a JSON object")
	}
	if object["type"] != "object" {
		return nil, terminalError("output schema root type must be object")
	}

	compiler := jsonschema.NewCompiler()
	if err := compiler.AddResource(outputSchemaURL, object); err != nil {
		return nil, terminalError(fmt.Sprintf("invalid output schema: %v", err))
	}
	compiled, err := compiler.Compile(outputSchemaURL)
	if err != nil {
		return nil, terminalError(fmt.Sprintf("invalid output schema: %v", err))
	}
	return &ResultValidator{schema: compiled}, nil
}

// Validate decodes exactly one JSON object and validates it without modifying
// or replacing the caller's schema.
func (v *ResultValidator) Validate(rawResult []byte) (Result, *Error) {
	if v == nil || v.schema == nil {
		return nil, terminalError("result validator is not initialized")
	}
	value, err := decodeOneJSON(rawResult)
	if err != nil {
		return nil, terminalError(fmt.Sprintf("invalid harness result: %v", err))
	}
	object, ok := value.(map[string]any)
	if !ok {
		return nil, terminalError("harness result must be a JSON object")
	}
	if err := v.schema.Validate(object); err != nil {
		return nil, terminalError(fmt.Sprintf("harness result does not conform to output schema: %v", err))
	}
	return Result(object), nil
}

// ValidateResult compiles rawSchema and validates rawResult against it.
func ValidateResult(rawSchema json.RawMessage, rawResult []byte) (Result, *Error) {
	validator, err := NewResultValidator(rawSchema)
	if err != nil {
		return nil, err
	}
	return validator.Validate(rawResult)
}

func decodeOneJSON(data []byte) (any, error) {
	decoder := json.NewDecoder(bytes.NewReader(data))
	decoder.UseNumber()
	var value any
	if err := decoder.Decode(&value); err != nil {
		return nil, err
	}
	var trailing any
	if err := decoder.Decode(&trailing); err != io.EOF {
		if err == nil {
			return nil, fmt.Errorf("multiple JSON values")
		}
		return nil, err
	}
	return value, nil
}

// Package lint validates graph relationships that are not structural JSON
// concerns.
package lint

import (
	"fmt"
	"strings"

	"github.com/tylergannon/tractor/graph"
)

// Severity determines whether a diagnostic prevents execution.
type Severity string

const (
	SeverityError   Severity = "error"
	SeverityWarning Severity = "warning"
	SeverityInfo    Severity = "info"
)

// EdgeRef identifies an authored edge as (from, to).
type EdgeRef [2]string

// Diagnostic describes one lint finding.
type Diagnostic struct {
	Rule     string   `json:"rule"`
	Severity Severity `json:"severity"`
	Message  string   `json:"message"`
	NodeID   string   `json:"node_id,omitempty"`
	Edge     *EdgeRef `json:"edge,omitempty"`
	Fix      string   `json:"fix,omitempty"`
}

// HarnessResolver returns the runtime harness selected for resolved provider
// and model values. It must use the same routing as execution.
type HarnessResolver func(provider, model string) (string, error)

// Options supplies the runtime knowledge required by implementation-dependent
// lint rules. Built-in types and fidelity modes are always known.
type Options struct {
	KnownCustomTypes  []string
	SupportedFidelity []string
	ResolveHarness    HarnessResolver
}

// Rule is an additional caller-provided lint rule.
type Rule interface {
	Name() string
	Apply(graph.Graph) []Diagnostic
}

// Validator runs the built-in rules with one runtime configuration.
type Validator struct {
	options options
}

// New constructs a validator. Empty options use the three specified fidelity
// modes and no registered custom handlers.
func New(opts Options) *Validator {
	return &Validator{options: normalizeOptions(opts)}
}

// Validate runs every built-in rule, followed by extra rules in caller order.
func (v *Validator) Validate(g graph.Graph, extraRules ...Rule) []Diagnostic {
	a := newAnalysis(g, v.options)
	diagnostics := a.builtInDiagnostics()
	for _, rule := range extraRules {
		if rule == nil {
			continue
		}
		for _, diagnostic := range rule.Apply(g) {
			if diagnostic.Rule == "" {
				diagnostic.Rule = rule.Name()
			}
			diagnostics = append(diagnostics, diagnostic)
		}
	}
	return diagnostics
}

// ValidateOrError returns all diagnostics and a ValidationError when any are
// error-severity.
func (v *Validator) ValidateOrError(g graph.Graph, extraRules ...Rule) ([]Diagnostic, error) {
	diagnostics := v.Validate(g, extraRules...)
	if !HasErrors(diagnostics) {
		return diagnostics, nil
	}
	return diagnostics, &ValidationError{Diagnostics: diagnostics}
}

// Validate runs the built-in rules with default options.
func Validate(g graph.Graph, extraRules ...Rule) []Diagnostic {
	return New(Options{}).Validate(g, extraRules...)
}

// ValidateOrError runs the built-in rules with default options.
func ValidateOrError(g graph.Graph, extraRules ...Rule) ([]Diagnostic, error) {
	return New(Options{}).ValidateOrError(g, extraRules...)
}

// HasErrors reports whether diagnostics contain an execution-blocking error.
func HasErrors(diagnostics []Diagnostic) bool {
	for _, diagnostic := range diagnostics {
		if diagnostic.Severity == SeverityError {
			return true
		}
	}
	return false
}

// ValidationError contains the complete diagnostic set from a failed
// validation.
type ValidationError struct {
	Diagnostics []Diagnostic
}

func (e *ValidationError) Error() string {
	if e == nil {
		return ""
	}
	messages := make([]string, 0, len(e.Diagnostics))
	for _, diagnostic := range e.Diagnostics {
		if diagnostic.Severity == SeverityError {
			messages = append(messages, fmt.Sprintf("%s: %s", diagnostic.Rule, diagnostic.Message))
		}
	}
	return "pipeline validation failed: " + strings.Join(messages, "; ")
}

type options struct {
	knownTypes        map[string]struct{}
	supportedFidelity map[string]struct{}
	resolveHarness    HarnessResolver
}

func normalizeOptions(opts Options) options {
	knownTypes := map[string]struct{}{
		"start": {}, "exit": {}, "codergen": {}, "tool": {},
		"parallel": {}, "parallel.fan_in": {},
	}
	for _, nodeType := range opts.KnownCustomTypes {
		knownTypes[nodeType] = struct{}{}
	}
	supported := map[string]struct{}{
		"full": {}, "compacted": {}, "none": {},
	}
	for _, fidelity := range opts.SupportedFidelity {
		supported[fidelity] = struct{}{}
	}
	return options{
		knownTypes:        knownTypes,
		supportedFidelity: supported,
		resolveHarness:    opts.ResolveHarness,
	}
}

func diagnostic(rule string, severity Severity, message, nodeID string) Diagnostic {
	return Diagnostic{Rule: rule, Severity: severity, Message: message, NodeID: nodeID}
}

func edgeDiagnostic(rule, message, from, to string) Diagnostic {
	edge := EdgeRef{from, to}
	return Diagnostic{
		Rule: rule, Severity: SeverityError, Message: message,
		NodeID: from, Edge: &edge,
	}
}

// Package claude implements Tractor's HarnessAdapter using Claude Code.
package claude

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"iter"
	"strings"
	"sync"
	"sync/atomic"
	"time"

	claudeagent "github.com/roasbeef/claude-agent-sdk-go"
	"github.com/tylergannon/tractor/harness"
)

const controlTimeout = 5 * time.Second

type nativeConfig struct {
	sessionID       string
	model           string
	reasoningEffort string
	workdir         string
	outputSchema    any
	fresh           bool
	stderr          io.Writer
}

type nativeSession interface {
	Send(context.Context, string) error
	Messages() iter.Seq[claudeagent.Message]
	Errors() <-chan error
	InterruptWithReceipt(context.Context) (*claudeagent.InterruptReceipt, error)
	Close() error
}

type sessionFactory func(context.Context, nativeConfig) (nativeSession, error)

// Adapter translates the neutral harness contract to Claude Code's SDK
// protocol. Native conversation history remains Claude Code's responsibility.
type Adapter struct {
	mu      sync.Mutex
	closed  bool
	stderr  io.Writer
	states  map[string]*sessionState
	factory sessionFactory
}

type sessionState struct {
	opMu    sync.Mutex
	mu      sync.Mutex
	workdir string
	fresh   bool
	active  *activeTurn
}

type activeTurn struct {
	session     nativeSession
	projector   *eventProjector
	interrupted atomic.Bool
	controls    sync.WaitGroup
}

// New constructs an adapter that launches Claude Code through the pinned SDK.
func New() *Adapter {
	return newAdapter(openNativeSession)
}

func newAdapter(factory sessionFactory) *Adapter {
	return &Adapter{states: make(map[string]*sessionState), factory: factory}
}

// SetStderr forwards Claude Code stderr. It must be called before use.
func (a *Adapter) SetStderr(stderr io.Writer) {
	a.mu.Lock()
	defer a.mu.Unlock()
	a.stderr = stderr
}

// CreateSession mints the native ID that the first Claude Code invocation
// receives through --session-id.
func (a *Adapter) CreateSession(model, workdir string) (string, *harness.Error) {
	if err := harness.ValidateCreateSessionInput(model, workdir); err != nil {
		return "", err
	}
	id, err := newUUID()
	if err != nil {
		return "", retryable(fmt.Sprintf("mint Claude session ID: %v", err))
	}
	a.mu.Lock()
	defer a.mu.Unlock()
	if a.closed {
		return "", terminal("Claude adapter is closed")
	}
	a.states[id] = &sessionState{workdir: workdir, fresh: true}
	return id, nil
}

// RunTurn runs one native structured-output turn and validates its result
// against the exact schema supplied by the caller.
func (a *Adapter) RunTurn(input harness.RunTurnInput, onEvent harness.OnEvent) (harness.Result, *harness.Error) {
	if err := harness.ValidateRunTurnInput(input, onEvent); err != nil {
		return nil, err
	}
	validator, validationErr := harness.NewResultValidator(input.OutputSchema)
	if validationErr != nil {
		return nil, validationErr
	}
	outputSchema, err := decodeSchema(input.OutputSchema)
	if err != nil {
		return nil, terminal(err.Error())
	}
	state, stateErr := a.state(input.SessionID)
	if stateErr != nil {
		return nil, stateErr
	}

	state.opMu.Lock()
	defer state.opMu.Unlock()
	fresh, workdirErr := prepareState(state, input.Workdir)
	if workdirErr != nil {
		return nil, workdirErr
	}
	sessionCtx := context.Background()
	var cancelSession context.CancelFunc
	var turnDeadline time.Time
	if input.Timeout > 0 {
		turnDeadline = time.Now().Add(input.Timeout)
		sessionCtx, cancelSession = context.WithDeadline(sessionCtx, turnDeadline.Add(controlTimeout))
	} else {
		sessionCtx, cancelSession = context.WithCancel(sessionCtx)
	}
	defer cancelSession()
	session, openErr := a.open(sessionCtx, nativeConfig{
		sessionID:       input.SessionID,
		model:           input.Model,
		reasoningEffort: input.ReasoningEffort,
		workdir:         input.Workdir,
		outputSchema:    outputSchema,
		fresh:           fresh,
	})
	if openErr != nil {
		return nil, categorize(openErr, false)
	}
	defer func() { _ = session.Close() }()

	projector := newEventProjector(onEvent)
	active := &activeTurn{session: session, projector: projector}
	state.mu.Lock()
	state.active = active
	state.mu.Unlock()
	defer finishActive(state, active)

	projector.user(input.Parts)
	if err := session.Send(sessionCtx, joinParts(input.Parts)); err != nil {
		return nil, categorize(err, false)
	}
	if !turnDeadline.IsZero() {
		input.Timeout = time.Until(turnDeadline)
		if input.Timeout <= 0 {
			input.Timeout = time.Nanosecond
		}
	}
	result, runErr := waitTurn(session, state, input, active)
	if runErr != nil {
		return nil, runErr
	}
	raw, err := json.Marshal(result.StructuredOutput)
	if err != nil {
		return nil, terminal(fmt.Sprintf("encode Claude structured output: %v", err))
	}
	return validator.Validate(raw)
}

// Steer best-effort sends ordered text parts to an active Claude stream.
func (a *Adapter) Steer(sessionID string, parts []harness.ContentPart) {
	if harness.ValidateContentParts(parts) != nil {
		return
	}
	state := a.lookup(sessionID)
	if state == nil {
		return
	}
	state.mu.Lock()
	active := state.active
	if active != nil {
		active.controls.Add(1)
	}
	state.mu.Unlock()
	if active == nil {
		return
	}
	defer active.controls.Done()

	ctx, cancel := context.WithTimeout(context.Background(), controlTimeout)
	defer cancel()
	if err := active.session.Send(ctx, joinParts(parts)); err != nil {
		return
	}
	state.mu.Lock()
	stillActive := state.active == active
	state.mu.Unlock()
	if stillActive {
		active.projector.user(parts)
	}
}

// Interrupt requests the native stop and returns immediately.
func (a *Adapter) Interrupt(sessionID string) {
	state := a.lookup(sessionID)
	if state == nil {
		return
	}
	state.mu.Lock()
	active := state.active
	if active != nil {
		active.controls.Add(1)
	}
	state.mu.Unlock()
	if active == nil {
		return
	}
	active.interrupted.Store(true)
	go func() {
		defer active.controls.Done()
		ctx, cancel := context.WithTimeout(context.Background(), controlTimeout)
		defer cancel()
		_, _ = active.session.InterruptWithReceipt(ctx)
	}()
}

// Compact sends Claude Code's native /compact command and waits for its
// terminal compact status.
func (a *Adapter) Compact(sessionID, workdir string) *harness.Error {
	if err := harness.ValidateSessionInput(sessionID, workdir); err != nil {
		return err
	}
	state, stateErr := a.state(sessionID)
	if stateErr != nil {
		return stateErr
	}
	if !state.opMu.TryLock() {
		return terminal("cannot compact a session with an active operation")
	}
	defer state.opMu.Unlock()
	state.mu.Lock()
	if state.active != nil {
		state.mu.Unlock()
		return terminal("cannot compact an active session")
	}
	if state.workdir != "" && state.workdir != workdir {
		state.mu.Unlock()
		return terminal("session working directory cannot change")
	}
	state.mu.Unlock()

	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Minute)
	defer cancel()
	session, err := a.open(ctx, nativeConfig{sessionID: sessionID, workdir: workdir})
	if err != nil {
		return categorize(err, false)
	}
	if err := session.Send(ctx, "/compact"); err != nil {
		return categorize(err, false)
	}
	messages, stop := readMessages(session)
	defer stop()
	for {
		var message claudeagent.Message
		select {
		case <-ctx.Done():
			return retryable("Claude compaction timed out")
		case nativeErr := <-session.Errors():
			return categorize(nativeErr, false)
		case next, ok := <-messages:
			if !ok {
				return retryable("Claude stream ended without a compaction result")
			}
			message = next
		}
		if mismatch := validateMessageSession(message, sessionID); mismatch != nil {
			return mismatch
		}
		status, ok := asStatus(message)
		if ok && status.Status == nil {
			switch status.CompactResult {
			case claudeagent.CompactResultSuccess:
				return nil
			case claudeagent.CompactResultFailed:
				message := strings.TrimSpace(status.CompactError)
				if message == "" {
					message = "Claude compaction failed"
				}
				return categorize(errors.New(message), false)
			}
		}
		if result, ok := asResult(message); ok && result.Subtype != "success" && result.Status != "success" {
			return categorize(errors.New(resultFailure(result)), false)
		}
	}
}

// Close interrupts active streams. Each turn otherwise owns and closes its
// native SDK process.
func (a *Adapter) Close() {
	a.mu.Lock()
	if a.closed {
		a.mu.Unlock()
		return
	}
	a.closed = true
	states := make([]*sessionState, 0, len(a.states))
	for _, state := range a.states {
		states = append(states, state)
	}
	a.mu.Unlock()
	for _, state := range states {
		state.mu.Lock()
		active := state.active
		state.mu.Unlock()
		if active != nil {
			active.interrupted.Store(true)
			ctx, cancel := context.WithTimeout(context.Background(), controlTimeout)
			_, _ = active.session.InterruptWithReceipt(ctx)
			cancel()
		}
	}
}

func (a *Adapter) open(ctx context.Context, config nativeConfig) (nativeSession, error) {
	a.mu.Lock()
	if a.closed {
		a.mu.Unlock()
		return nil, errors.New("claude adapter is closed")
	}
	config.stderr = a.stderr
	factory := a.factory
	a.mu.Unlock()
	return factory(ctx, config)
}

func (a *Adapter) state(sessionID string) (*sessionState, *harness.Error) {
	a.mu.Lock()
	defer a.mu.Unlock()
	if a.closed {
		return nil, terminal("Claude adapter is closed")
	}
	state := a.states[sessionID]
	if state == nil {
		state = &sessionState{}
		a.states[sessionID] = state
	}
	return state, nil
}

func (a *Adapter) lookup(sessionID string) *sessionState {
	a.mu.Lock()
	defer a.mu.Unlock()
	return a.states[sessionID]
}

func prepareState(state *sessionState, workdir string) (bool, *harness.Error) {
	state.mu.Lock()
	defer state.mu.Unlock()
	if state.workdir != "" && state.workdir != workdir {
		return false, terminal("session working directory cannot change")
	}
	if state.workdir == "" {
		state.workdir = workdir
	}
	return state.fresh, nil
}

func finishActive(state *sessionState, active *activeTurn) {
	state.mu.Lock()
	if state.active == active {
		state.active = nil
	}
	state.mu.Unlock()
	active.controls.Wait()
}

func waitTurn(session nativeSession, state *sessionState, input harness.RunTurnInput, active *activeTurn) (claudeagent.ResultMessage, *harness.Error) {
	messages, stop := readMessages(session)
	defer stop()

	var timer <-chan time.Time
	var timeout *time.Timer
	if input.Timeout > 0 {
		timeout = time.NewTimer(input.Timeout)
		timer = timeout.C
		defer timeout.Stop()
	}
	timedOut := false
	for {
		select {
		case nativeErr := <-session.Errors():
			return claudeagent.ResultMessage{}, categorize(nativeErr, active.interrupted.Load())
		case <-timer:
			if timedOut {
				return claudeagent.ResultMessage{}, interrupted("turn timed out and was interrupted")
			}
			timedOut = true
			active.interrupted.Store(true)
			ctx, cancel := context.WithTimeout(context.Background(), controlTimeout)
			_, _ = session.InterruptWithReceipt(ctx)
			cancel()
			timer = time.After(controlTimeout)
		case message, ok := <-messages:
			if !ok {
				if timedOut || active.interrupted.Load() {
					return claudeagent.ResultMessage{}, interrupted("turn was interrupted")
				}
				return claudeagent.ResultMessage{}, retryable("Claude stream ended without a result")
			}
			if mismatch := validateMessageSession(message, input.SessionID); mismatch != nil {
				return claudeagent.ResultMessage{}, mismatch
			}
			promoteMaterialized(state, message, input.SessionID)
			if failure := assistantFailure(message); failure != nil {
				return claudeagent.ResultMessage{}, failure
			}
			active.projector.message(message)
			if result, ok := asResult(message); ok {
				if timedOut || active.interrupted.Load() {
					return claudeagent.ResultMessage{}, interrupted("turn was interrupted")
				}
				if result.Subtype != "success" && result.Status != "success" {
					return claudeagent.ResultMessage{}, categorize(errors.New(resultFailure(result)), false)
				}
				if result.StructuredOutput == nil {
					return claudeagent.ResultMessage{}, terminal("Claude completed without structured output")
				}
				return result, nil
			}
		}
	}
}

func assistantFailure(message claudeagent.Message) *harness.Error {
	var code claudeagent.AssistantMessageError
	switch assistant := message.(type) {
	case claudeagent.AssistantMessage:
		code = assistant.Error
	case *claudeagent.AssistantMessage:
		code = assistant.Error
	}
	if code == "" {
		return nil
	}
	messageText := "Claude assistant error: " + string(code)
	switch code {
	case claudeagent.AssistantMessageErrorRateLimit,
		claudeagent.AssistantMessageErrorOverloaded,
		claudeagent.AssistantMessageErrorServerError:
		return retryable(messageText)
	default:
		return terminal(messageText)
	}
}

func readMessages(session nativeSession) (<-chan claudeagent.Message, func()) {
	messages := make(chan claudeagent.Message)
	done := make(chan struct{})
	stop := make(chan struct{})
	go func() {
		defer close(done)
		defer close(messages)
		for message := range session.Messages() {
			select {
			case messages <- message:
			case <-stop:
				return
			}
		}
	}()
	return messages, func() {
		close(stop)
		_ = session.Close()
		<-done
	}
}

func promoteMaterialized(state *sessionState, message claudeagent.Message, sessionID string) {
	envelope, err := nativeEnvelope(message)
	if err != nil || envelope.SessionID != sessionID || (envelope.Type == "system" && envelope.Subtype == "init") {
		return
	}
	state.mu.Lock()
	state.fresh = false
	state.mu.Unlock()
}

func validateMessageSession(message claudeagent.Message, sessionID string) *harness.Error {
	envelope, err := nativeEnvelope(message)
	if err != nil {
		return terminal(fmt.Sprintf("decode Claude message: %v", err))
	}
	if envelope.SessionID != "" && envelope.SessionID != sessionID {
		return terminal("Claude returned a different session ID")
	}
	if envelope.Type == "system" && envelope.Subtype == "init" && envelope.SessionID == "" {
		return terminal("Claude init omitted its session ID")
	}
	return nil
}

type messageEnvelope struct {
	Type      string `json:"type"`
	Subtype   string `json:"subtype"`
	SessionID string `json:"session_id"`
}

func nativeEnvelope(message claudeagent.Message) (messageEnvelope, error) {
	raw, err := json.Marshal(message)
	if err != nil {
		return messageEnvelope{}, err
	}
	var envelope messageEnvelope
	err = json.Unmarshal(raw, &envelope)
	return envelope, err
}

func decodeSchema(raw json.RawMessage) (any, error) {
	var schema any
	if err := json.Unmarshal(raw, &schema); err != nil {
		return nil, fmt.Errorf("decode output schema: %w", err)
	}
	return schema, nil
}

func joinParts(parts []harness.ContentPart) string {
	texts := make([]string, 0, len(parts))
	for _, part := range parts {
		texts = append(texts, part.Text)
	}
	return strings.Join(texts, "\n\n")
}

func newUUID() (string, error) {
	var value [16]byte
	if _, err := rand.Read(value[:]); err != nil {
		return "", err
	}
	value[6] = value[6]&0x0f | 0x40
	value[8] = value[8]&0x3f | 0x80
	var encoded [32]byte
	hex.Encode(encoded[:], value[:])
	return fmt.Sprintf("%s-%s-%s-%s-%s", encoded[0:8], encoded[8:12], encoded[12:16], encoded[16:20], encoded[20:32]), nil
}

func resultFailure(result claudeagent.ResultMessage) string {
	parts := append([]string(nil), result.Errors...)
	if result.TerminalReason != nil {
		parts = append(parts, string(*result.TerminalReason))
	}
	if len(parts) == 0 {
		parts = append(parts, result.Subtype)
	}
	return "Claude turn failed: " + strings.Join(parts, "; ")
}

func categorize(err error, wasInterrupted bool) *harness.Error {
	if err == nil {
		return nil
	}
	if wasInterrupted || errors.Is(err, context.Canceled) || errors.Is(err, context.DeadlineExceeded) {
		return interrupted(err.Error())
	}
	message := strings.TrimSpace(err.Error())
	if message == "" {
		message = "Claude operation failed"
	}
	lower := strings.ToLower(message)
	for _, marker := range []string{"rate limit", "temporarily unavailable", "service unavailable", "overloaded", "connection reset", "broken pipe", "unexpected eof"} {
		if strings.Contains(lower, marker) {
			return retryable(message)
		}
	}
	for _, marker := range []string{"no conversation found", "not found", "invalid", "model", "structured output", "permission"} {
		if strings.Contains(lower, marker) {
			return terminal(message)
		}
	}
	return retryable(message)
}

func terminal(message string) *harness.Error {
	return &harness.Error{Category: harness.ErrorTerminal, Message: message}
}

func retryable(message string) *harness.Error {
	return &harness.Error{Category: harness.ErrorRetryable, Message: message}
}

func interrupted(message string) *harness.Error {
	return &harness.Error{Category: harness.ErrorInterrupted, Message: message}
}

var _ harness.HarnessAdapter = (*Adapter)(nil)

// Package codex implements Tractor's HarnessAdapter using Codex app-server.
package codex

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"strings"
	"sync"
	"sync/atomic"
	"time"

	"github.com/tylergannon/tractor/harness"
	"github.com/tylergannon/tractor/harness/codex/schema"
)

const (
	requestTimeout = 30 * time.Second
	controlTimeout = 5 * time.Second
)

// Adapter translates the neutral harness contract to Codex app-server's v2
// stdio protocol.
type Adapter struct {
	config processConfig
	mu     sync.Mutex
	closed bool
	states map[string]*sessionState
}

type sessionState struct {
	opMu    sync.Mutex
	mu      sync.Mutex
	workdir string
	fresh   *connection
	active  *activeTurn
}

type activeTurn struct {
	connection  *connection
	turnID      string
	projector   *eventProjector
	interrupted atomic.Bool
	controls    sync.WaitGroup
}

// New constructs an adapter that launches `codex app-server --stdio`.
func New() *Adapter {
	return newAdapter(defaultProcessConfig())
}

func newAdapter(config processConfig) *Adapter {
	return &Adapter{config: config, states: make(map[string]*sessionState)}
}

// SetStderr forwards app-server stderr while retaining it for diagnostics.
// It must be called before the adapter is used.
func (a *Adapter) SetStderr(stderr io.Writer) {
	a.mu.Lock()
	defer a.mu.Unlock()
	a.config.stderr = stderr
}

// CreateSession starts a durable Codex thread. Its app-server process is kept
// through the first turn because a thread with no turn is not yet resumable.
func (a *Adapter) CreateSession(model, workdir string) (string, *harness.Error) {
	if err := harness.ValidateCreateSessionInput(model, workdir); err != nil {
		return "", err
	}
	connection, err := a.start()
	if err != nil {
		return "", categorize(err, false)
	}
	keep := false
	defer func() {
		if !keep {
			connection.close()
		}
	}()

	ctx, cancel := context.WithTimeout(context.Background(), requestTimeout)
	defer cancel()
	if err := connection.initialize(ctx); err != nil {
		return "", categorize(err, false)
	}
	result, err := connection.call(ctx, "thread/start", map[string]any{
		"model":              model,
		"cwd":                workdir,
		"approvalPolicy":     "never",
		"sandbox":            "danger-full-access",
		"serviceName":        "tractor",
		"sessionStartSource": "startup",
	})
	if err != nil {
		return "", categorize(err, false)
	}
	threadID, err := decodeThreadID(result)
	if err != nil {
		return "", categorize(err, false)
	}

	a.mu.Lock()
	if a.closed {
		a.mu.Unlock()
		return "", terminal("Codex adapter is closed")
	}
	a.states[threadID] = &sessionState{workdir: workdir, fresh: connection}
	a.mu.Unlock()
	keep = true
	return threadID, nil
}

// RunTurn resumes or uses the retained fresh process, runs one structured
// turn, emits completed logical events, and validates the exact result schema.
func (a *Adapter) RunTurn(input harness.RunTurnInput, onEvent harness.OnEvent) (harness.Result, *harness.Error) {
	if err := harness.ValidateRunTurnInput(input, onEvent); err != nil {
		return nil, err
	}
	validator, validationErr := harness.NewResultValidator(input.OutputSchema)
	if validationErr != nil {
		return nil, validationErr
	}
	state, stateErr := a.state(input.SessionID)
	if stateErr != nil {
		return nil, stateErr
	}

	state.opMu.Lock()
	defer state.opMu.Unlock()
	connection, fresh, openErr := a.openSession(state, input.SessionID, input.Workdir)
	if openErr != nil {
		return nil, openErr
	}
	defer func() {
		state.mu.Lock()
		if state.fresh == connection {
			state.fresh = nil
		}
		state.mu.Unlock()
		connection.close()
	}()

	params, err := turnStartParams(input)
	if err != nil {
		return nil, terminal(err.Error())
	}
	ctx, cancel := context.WithTimeout(context.Background(), requestTimeout)
	result, err := connection.call(ctx, "turn/start", params)
	cancel()
	if err != nil {
		return nil, categorize(err, false)
	}
	turnID, err := decodeTurnID(result)
	if err != nil {
		return nil, terminal(err.Error())
	}
	projector := newEventProjector(onEvent)
	active := &activeTurn{connection: connection, turnID: turnID, projector: projector}
	state.mu.Lock()
	state.active = active
	if fresh && state.fresh == connection {
		state.fresh = nil
	}
	if state.workdir == "" {
		state.workdir = input.Workdir
	}
	state.mu.Unlock()
	projector.user(input.Parts)
	defer finishActive(state, active)

	raw, runErr := waitTurn(connection, input, turnID, active)
	if runErr != nil {
		return nil, runErr
	}
	return validator.Validate(raw)
}

// Steer best-effort delivers ordered text parts to a currently active turn.
func (a *Adapter) Steer(sessionID string, parts []harness.ContentPart) {
	if harness.ValidateContentParts(parts) != nil {
		return
	}
	state := a.lookup(sessionID)
	if state == nil {
		return
	}
	state.mu.Lock()
	active := state.active
	if active != nil {
		active.controls.Add(1)
	}
	state.mu.Unlock()
	if active == nil {
		return
	}
	defer active.controls.Done()

	ctx, cancel := context.WithTimeout(context.Background(), controlTimeout)
	defer cancel()
	_, err := active.connection.call(ctx, "turn/steer", map[string]any{
		"threadId":       sessionID,
		"expectedTurnId": active.turnID,
		"input":          nativeInput(parts),
	})
	if err != nil {
		return
	}
	state.mu.Lock()
	stillActive := state.active == active
	state.mu.Unlock()
	if stillActive {
		active.projector.user(parts)
	}
}

// Interrupt requests the native turn stop and returns immediately.
func (a *Adapter) Interrupt(sessionID string) {
	state := a.lookup(sessionID)
	if state == nil {
		return
	}
	state.mu.Lock()
	active := state.active
	if active != nil {
		active.controls.Add(1)
	}
	state.mu.Unlock()
	if active == nil {
		return
	}
	active.interrupted.Store(true)
	go func() {
		defer active.controls.Done()
		ctx, cancel := context.WithTimeout(context.Background(), controlTimeout)
		defer cancel()
		_, _ = active.connection.call(ctx, "turn/interrupt", map[string]any{
			"threadId": sessionID,
			"turnId":   active.turnID,
		})
	}()
}

// Compact blocks until Codex reports completion of the matching
// contextCompaction item.
func (a *Adapter) Compact(sessionID, workdir string) *harness.Error {
	if err := harness.ValidateSessionInput(sessionID, workdir); err != nil {
		return err
	}
	state, stateErr := a.state(sessionID)
	if stateErr != nil {
		return stateErr
	}
	if !state.opMu.TryLock() {
		return terminal("cannot compact a session with an active operation")
	}
	defer state.opMu.Unlock()
	state.mu.Lock()
	if state.active != nil {
		state.mu.Unlock()
		return terminal("cannot compact an active session")
	}
	state.mu.Unlock()

	connection, fresh, openErr := a.openSession(state, sessionID, workdir)
	if openErr != nil {
		return openErr
	}
	if !fresh {
		defer connection.close()
	}
	ctx, cancel := context.WithTimeout(context.Background(), requestTimeout)
	_, err := connection.call(ctx, "thread/compact/start", map[string]any{"threadId": sessionID})
	cancel()
	if err != nil {
		if fresh && !isRPCError(err) {
			a.dropFresh(state, connection)
			connection.close()
		}
		return categorize(err, false)
	}
	if err := waitCompaction(connection, sessionID); err != nil {
		if fresh && err.Category == harness.ErrorRetryable {
			a.dropFresh(state, connection)
			connection.close()
		}
		return err
	}
	return nil
}

// Close releases retained fresh-session and live app-server processes.
func (a *Adapter) Close() {
	a.mu.Lock()
	if a.closed {
		a.mu.Unlock()
		return
	}
	a.closed = true
	states := make([]*sessionState, 0, len(a.states))
	for _, state := range a.states {
		states = append(states, state)
	}
	a.mu.Unlock()

	connections := make(map[*connection]struct{})
	for _, state := range states {
		state.mu.Lock()
		if state.fresh != nil {
			connections[state.fresh] = struct{}{}
		}
		if state.active != nil {
			connections[state.active.connection] = struct{}{}
		}
		state.mu.Unlock()
	}
	for connection := range connections {
		connection.close()
	}
}

func (a *Adapter) start() (*connection, error) {
	a.mu.Lock()
	defer a.mu.Unlock()
	if a.closed {
		return nil, errors.New("codex adapter is closed")
	}
	config := a.config
	config.args = append([]string(nil), config.args...)
	config.env = append([]string(nil), config.env...)
	return startConnection(config)
}

func (a *Adapter) state(sessionID string) (*sessionState, *harness.Error) {
	a.mu.Lock()
	defer a.mu.Unlock()
	if a.closed {
		return nil, terminal("Codex adapter is closed")
	}
	state := a.states[sessionID]
	if state == nil {
		state = &sessionState{}
		a.states[sessionID] = state
	}
	return state, nil
}

func (a *Adapter) lookup(sessionID string) *sessionState {
	a.mu.Lock()
	defer a.mu.Unlock()
	return a.states[sessionID]
}

func (a *Adapter) openSession(state *sessionState, sessionID, workdir string) (*connection, bool, *harness.Error) {
	state.mu.Lock()
	if state.workdir != "" && state.workdir != workdir {
		state.mu.Unlock()
		return nil, false, terminal("session working directory cannot change")
	}
	connection := state.fresh
	state.mu.Unlock()
	if connection != nil {
		return connection, true, nil
	}

	connection, err := a.start()
	if err != nil {
		return nil, false, categorize(err, false)
	}
	keep := false
	defer func() {
		if !keep {
			connection.close()
		}
	}()
	ctx, cancel := context.WithTimeout(context.Background(), requestTimeout)
	defer cancel()
	if err := connection.initialize(ctx); err != nil {
		return nil, false, categorize(err, false)
	}
	result, err := connection.call(ctx, "thread/resume", map[string]any{
		"threadId":       sessionID,
		"cwd":            workdir,
		"approvalPolicy": "never",
		"sandbox":        "danger-full-access",
	})
	if err != nil {
		return nil, false, categorize(err, false)
	}
	resumedID, err := decodeThreadID(result)
	if err != nil {
		return nil, false, terminal(err.Error())
	}
	if resumedID != sessionID {
		return nil, false, terminal("thread/resume returned a different session ID")
	}
	state.mu.Lock()
	if state.workdir == "" {
		state.workdir = workdir
	}
	state.mu.Unlock()
	keep = true
	return connection, false, nil
}

func (a *Adapter) dropFresh(state *sessionState, connection *connection) {
	state.mu.Lock()
	if state.fresh == connection {
		state.fresh = nil
	}
	state.mu.Unlock()
}

func finishActive(state *sessionState, active *activeTurn) {
	state.mu.Lock()
	if state.active == active {
		state.active = nil
	}
	state.mu.Unlock()
	active.controls.Wait()
}

func turnStartParams(input harness.RunTurnInput) (schema.TurnStartParams, error) {
	var outputSchema any
	if err := json.Unmarshal(input.OutputSchema, &outputSchema); err != nil {
		return schema.TurnStartParams{}, fmt.Errorf("decode output schema: %w", err)
	}
	model := input.Model
	workdir := input.Workdir
	return schema.TurnStartParams{
		ThreadID:       input.SessionID,
		Input:          nativeInput(input.Parts),
		Model:          schema.TurnStartParamsModel(&model),
		Cwd:            schema.TurnStartParamsCwd(&workdir),
		Effort:         schema.ReasoningEffort(input.ReasoningEffort),
		OutputSchema:   outputSchema,
		ApprovalPolicy: "never",
		SandboxPolicy:  map[string]any{"type": "dangerFullAccess"},
	}, nil
}

func nativeInput(parts []harness.ContentPart) []schema.UserInput {
	result := make([]schema.UserInput, 0, len(parts))
	for _, part := range parts {
		result = append(result, map[string]any{
			"type":          "text",
			"text":          part.Text,
			"text_elements": []any{},
		})
	}
	return result
}

func waitTurn(connection *connection, input harness.RunTurnInput, turnID string, active *activeTurn) ([]byte, *harness.Error) {
	ctx := context.Background()
	var cancel context.CancelFunc
	if input.Timeout > 0 {
		ctx, cancel = context.WithTimeout(ctx, input.Timeout)
		defer cancel()
	}
	result, err := readTurn(ctx, connection, input.SessionID, turnID, active)
	if !errors.Is(err, context.DeadlineExceeded) {
		return result, categorizeTurnError(err, active.interrupted.Load())
	}

	active.interrupted.Store(true)
	interruptCtx, interruptCancel := context.WithTimeout(context.Background(), controlTimeout)
	_, _ = connection.call(interruptCtx, "turn/interrupt", map[string]any{
		"threadId": input.SessionID,
		"turnId":   turnID,
	})
	interruptCancel()
	drainCtx, drainCancel := context.WithTimeout(context.Background(), controlTimeout)
	_, _ = readTurn(drainCtx, connection, input.SessionID, turnID, active)
	drainCancel()
	return nil, interrupted("turn timed out and was interrupted")
}

func readTurn(ctx context.Context, connection *connection, threadID, turnID string, active *activeTurn) ([]byte, error) {
	var assistantText string
	for {
		message, err := connection.next(ctx)
		if err != nil {
			return nil, err
		}
		if len(message.ID) > 0 && message.Method != "" {
			return nil, refuseServerRequest(connection, message)
		}
		if !messageMatches(message.Params, threadID, turnID) {
			continue
		}
		switch message.Method {
		case "item/started":
			active.projector.itemStarted(message.Params)
		case "item/completed":
			if text, ok := active.projector.itemCompleted(message.Params); ok {
				assistantText = text
			}
		case "thread/tokenUsage/updated":
			active.projector.usage(message.Params)
		case "turn/completed":
			status, failure, ok := decodeCompletedTurn(message.Params, threadID, turnID)
			if !ok {
				continue
			}
			switch status {
			case "completed":
				if active.interrupted.Load() {
					return nil, context.Canceled
				}
				if strings.TrimSpace(assistantText) == "" {
					return nil, errors.New("codex completed without an assistant result")
				}
				return []byte(assistantText), nil
			case "interrupted":
				return nil, context.Canceled
			case "failed":
				if failure == "" {
					failure = "Codex turn failed"
				}
				return nil, errors.New(failure)
			default:
				return nil, fmt.Errorf("codex turn ended with status %q", status)
			}
		case "error":
			return nil, decodeErrorNotification(message.Params)
		}
	}
}

func waitCompaction(connection *connection, threadID string) *harness.Error {
	ctx, cancel := context.WithTimeout(context.Background(), requestTimeout)
	defer cancel()
	var compactTurnID string
	for {
		message, err := connection.next(ctx)
		if err != nil {
			return categorize(err, false)
		}
		if len(message.ID) > 0 && message.Method != "" {
			return categorize(refuseServerRequest(connection, message), false)
		}
		if !messageMatchesThread(message.Params, threadID) {
			continue
		}
		switch message.Method {
		case "turn/started":
			compactTurnID = notificationTurnID(message.Params)
		case "item/completed":
			item, ok := decodeItem(message.Params)
			if ok && item.Type == "contextCompaction" {
				turnID := notificationTurnID(message.Params)
				if compactTurnID == "" || turnID == compactTurnID {
					return nil
				}
			}
		case "turn/completed":
			status, failure, ok := decodeCompletedTurn(message.Params, threadID, compactTurnID)
			if ok && status != "completed" {
				if failure == "" {
					failure = "Codex compaction failed"
				}
				return categorize(errors.New(failure), false)
			}
		case "error":
			return categorize(decodeErrorNotification(message.Params), false)
		}
	}
}

func refuseServerRequest(connection *connection, message rpcMessage) error {
	result := map[string]any{"decision": "decline"}
	switch message.Method {
	case "execCommandApproval", "applyPatchApproval":
		result["decision"] = "denied"
	case "item/tool/requestUserInput":
		result = map[string]any{"answers": map[string]any{}}
	case "mcpServer/elicitation/request":
		result = map[string]any{"action": "decline"}
	case "item/permissions/requestApproval":
		result = map[string]any{"permissions": map[string]any{}, "scope": "turn"}
	}
	if err := connection.respond(message, result, nil); err != nil {
		return err
	}
	return fmt.Errorf("unexpected interactive Codex request %q", message.Method)
}

func decodeThreadID(raw json.RawMessage) (string, error) {
	var response struct {
		Thread struct {
			ID string `json:"id"`
		} `json:"thread"`
	}
	if err := json.Unmarshal(raw, &response); err != nil {
		return "", fmt.Errorf("decode Codex thread response: %w", err)
	}
	if response.Thread.ID == "" {
		return "", errors.New("codex thread response omitted thread.id")
	}
	return response.Thread.ID, nil
}

func decodeTurnID(raw json.RawMessage) (string, error) {
	var response struct {
		Turn struct {
			ID string `json:"id"`
		} `json:"turn"`
	}
	if err := json.Unmarshal(raw, &response); err != nil {
		return "", fmt.Errorf("decode Codex turn response: %w", err)
	}
	if response.Turn.ID == "" {
		return "", errors.New("codex turn response omitted turn.id")
	}
	return response.Turn.ID, nil
}

func decodeCompletedTurn(raw json.RawMessage, threadID, turnID string) (string, string, bool) {
	var notification struct {
		ThreadID string `json:"threadId"`
		Turn     struct {
			ID     string `json:"id"`
			Status string `json:"status"`
			Error  *struct {
				Message string `json:"message"`
			} `json:"error"`
		} `json:"turn"`
	}
	if json.Unmarshal(raw, &notification) != nil || notification.ThreadID != threadID || notification.Turn.ID != turnID {
		return "", "", false
	}
	failure := ""
	if notification.Turn.Error != nil {
		failure = notification.Turn.Error.Message
	}
	return notification.Turn.Status, failure, true
}

func decodeErrorNotification(raw json.RawMessage) error {
	var notification struct {
		Message string `json:"message"`
		Error   *struct {
			Message           string `json:"message"`
			AdditionalDetails string `json:"additionalDetails"`
		} `json:"error"`
	}
	if json.Unmarshal(raw, &notification) != nil {
		return fmt.Errorf("codex error notification: %s", strings.TrimSpace(string(raw)))
	}
	if notification.Message != "" {
		return errors.New(notification.Message)
	}
	if notification.Error != nil && notification.Error.Message != "" {
		if notification.Error.AdditionalDetails != "" {
			return fmt.Errorf("%s: %s", notification.Error.Message, notification.Error.AdditionalDetails)
		}
		return errors.New(notification.Error.Message)
	}
	return errors.New("codex emitted an empty error notification")
}

func messageMatches(raw json.RawMessage, threadID, turnID string) bool {
	var envelope struct {
		ThreadID string `json:"threadId"`
		TurnID   string `json:"turnId"`
		Turn     struct {
			ID string `json:"id"`
		} `json:"turn"`
	}
	if json.Unmarshal(raw, &envelope) != nil || envelope.ThreadID != threadID {
		return false
	}
	if envelope.TurnID != "" {
		return envelope.TurnID == turnID
	}
	return envelope.Turn.ID == turnID
}

func messageMatchesThread(raw json.RawMessage, threadID string) bool {
	var envelope struct {
		ThreadID string `json:"threadId"`
	}
	return json.Unmarshal(raw, &envelope) == nil && envelope.ThreadID == threadID
}

func notificationTurnID(raw json.RawMessage) string {
	var envelope struct {
		TurnID string `json:"turnId"`
		Turn   struct {
			ID string `json:"id"`
		} `json:"turn"`
	}
	_ = json.Unmarshal(raw, &envelope)
	if envelope.TurnID != "" {
		return envelope.TurnID
	}
	return envelope.Turn.ID
}

func categorizeTurnError(err error, wasInterrupted bool) *harness.Error {
	if err == nil {
		return nil
	}
	if wasInterrupted || errors.Is(err, context.Canceled) || errors.Is(err, context.DeadlineExceeded) {
		return interrupted("turn was interrupted")
	}
	return categorize(err, false)
}

func categorize(err error, wasInterrupted bool) *harness.Error {
	if err == nil {
		return nil
	}
	if wasInterrupted || errors.Is(err, context.Canceled) || errors.Is(err, context.DeadlineExceeded) {
		return interrupted(err.Error())
	}
	message := strings.TrimSpace(err.Error())
	if message == "" {
		message = "Codex operation failed"
	}
	lower := strings.ToLower(message)
	for _, marker := range []string{"rate limit", "temporarily unavailable", "service unavailable", "overloaded", "connection reset", "broken pipe", "unexpected eof"} {
		if strings.Contains(lower, marker) {
			return &harness.Error{Category: harness.ErrorRetryable, Message: message}
		}
	}
	for _, marker := range []string{"invalid_request", "invalid json schema", "invalid_json_schema", "not found", "unknown thread", "model", "interactive"} {
		if strings.Contains(lower, marker) {
			return terminal(message)
		}
	}
	if isRPCError(err) {
		return terminal(message)
	}
	return &harness.Error{Category: harness.ErrorRetryable, Message: message}
}

func terminal(message string) *harness.Error {
	return &harness.Error{Category: harness.ErrorTerminal, Message: message}
}

func interrupted(message string) *harness.Error {
	return &harness.Error{Category: harness.ErrorInterrupted, Message: message}
}

var _ harness.HarnessAdapter = (*Adapter)(nil)

