package engine

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"

	"github.com/tylergannon/tractor/graph"
	"github.com/tylergannon/tractor/harness"
	"github.com/tylergannon/tractor/lint"
)

// BranchResult is the durable evidence produced for one parallel branch.
type BranchResult struct {
	BranchID  string           `json:"branch_id"`
	Outcome   *harness.Outcome `json:"outcome,omitempty"`
	Error     *harness.Error   `json:"error,omitempty"`
	Notes     string           `json:"notes"`
	Path      []string         `json:"path"`
	Workdir   string           `json:"workdir"`
	StageDirs []string         `json:"stage_dirs"`
	Segments  []string         `json:"segments"`
}

// MarshalJSON keeps required collection fields as arrays for strict readers.
func (r BranchResult) MarshalJSON() ([]byte, error) {
	type branchResult BranchResult
	normalized := branchResult(r)
	if normalized.Path == nil {
		normalized.Path = []string{}
	}
	if normalized.StageDirs == nil {
		normalized.StageDirs = []string{}
	}
	if normalized.Segments == nil {
		normalized.Segments = []string{}
	}
	return json.Marshal(normalized)
}

// UnmarshalJSON enforces the complete, closed BranchResult evidence shape.
func (r *BranchResult) UnmarshalJSON(data []byte) error {
	type wireBranchResult struct {
		BranchID  *string         `json:"branch_id"`
		Outcome   json.RawMessage `json:"outcome"`
		Error     json.RawMessage `json:"error"`
		Notes     *string         `json:"notes"`
		Path      *[]string       `json:"path"`
		Workdir   *string         `json:"workdir"`
		StageDirs *[]string       `json:"stage_dirs"`
		Segments  *[]string       `json:"segments"`
	}
	var wire wireBranchResult
	if err := decodeStrictJSON(data, &wire); err != nil {
		return err
	}
	if wire.BranchID == nil || wire.Notes == nil || wire.Path == nil || wire.Workdir == nil || wire.StageDirs == nil || wire.Segments == nil {
		return fmt.Errorf("branch result is missing a required field")
	}
	if strings.TrimSpace(*wire.BranchID) == "" {
		return fmt.Errorf("branch_id must not be empty")
	}
	if strings.TrimSpace(*wire.Workdir) == "" {
		return fmt.Errorf("workdir must not be empty")
	}
	outcomePresent := len(wire.Outcome) != 0
	errorPresent := len(wire.Error) != 0
	if outcomePresent == errorPresent {
		return fmt.Errorf("branch result must contain exactly one of outcome or error")
	}

	result := BranchResult{
		BranchID:  *wire.BranchID,
		Notes:     *wire.Notes,
		Path:      *wire.Path,
		Workdir:   *wire.Workdir,
		StageDirs: *wire.StageDirs,
		Segments:  *wire.Segments,
	}
	if outcomePresent {
		if bytes.Equal(bytes.TrimSpace(wire.Outcome), []byte("null")) {
			return fmt.Errorf("outcome must not be null")
		}
		var encoded struct {
			Next  string  `json:"next"`
			Notes *string `json:"notes"`
		}
		if err := decodeStrictJSON(wire.Outcome, &encoded); err != nil {
			return fmt.Errorf("decode outcome: %w", err)
		}
		if encoded.Notes == nil {
			return fmt.Errorf("outcome is missing notes")
		}
		result.Outcome = &harness.Outcome{Next: encoded.Next, Notes: *encoded.Notes}
	} else {
		if bytes.Equal(bytes.TrimSpace(wire.Error), []byte("null")) {
			return fmt.Errorf("error must not be null")
		}
		var runErr harness.Error
		if err := decodeStrictJSON(wire.Error, &runErr); err != nil {
			return fmt.Errorf("decode error: %w", err)
		}
		if !runErr.Valid() {
			return fmt.Errorf("branch error is invalid")
		}
		result.Error = &runErr
	}
	*r = result
	return nil
}

// FanInHandler evaluates branch evidence through the codergen path.
type FanInHandler struct {
	codergen *CodergenHandler
}

// NewFanInHandler constructs a fan-in handler with the codergen configuration.
func NewFanInHandler(config CodergenConfig) *FanInHandler {
	return &FanInHandler{codergen: NewCodergenHandler(config)}
}

// Execute loads the owning parallel's evidence and runs the fan-in turn.
func (h *FanInHandler) Execute(node graph.Node, offered []graph.Edge, scope ExecutionScope, pipeline *graph.Graph) (harness.Outcome, *harness.Error) {
	join, ok := node.(*graph.FanInNode)
	if !ok {
		return harness.Outcome{}, terminalError(fmt.Sprintf("fan-in handler cannot execute node type %s", node.NodeType()))
	}
	owner, err := lint.ParallelForFanIn(*pipeline, join.ID)
	if err != nil {
		return harness.Outcome{}, terminalError(err.Error())
	}
	evidencePath := filepath.Join(filepath.Dir(scope.StageDir), "latest", owner.ID, "branches.json")
	results, err := readBranchResults(evidencePath)
	if err != nil {
		return harness.Outcome{}, terminalError(fmt.Sprintf("read branch evidence for %s: %v", owner.ID, err))
	}
	branchRoots := make(map[string]struct{}, len(owner.Edges))
	for _, edge := range owner.Edges {
		branchRoots[edge.To] = struct{}{}
	}
	for _, result := range results {
		if _, ok := branchRoots[result.BranchID]; !ok {
			return harness.Outcome{}, terminalError(fmt.Sprintf("branch evidence for %s names unknown branch %q", owner.ID, result.BranchID))
		}
	}

	prompt := ""
	if join.Prompt.Present {
		prompt = join.Prompt.Value
	}
	if prompt == "" {
		prompt = "Evaluate the results of the parallel branches."
	}
	prompt = strings.ReplaceAll(prompt, "$goal", scope.Goal)
	prompt += "\n\n" + renderBranchResults(results)
	return h.codergen.executeTurn(join, &join.LLMNodeFields, offered, scope, pipeline, prompt)
}

func readBranchResults(path string) ([]BranchResult, error) {
	raw, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	var results []BranchResult
	if err := decodeStrictJSON(raw, &results); err != nil {
		return nil, err
	}
	if len(results) == 0 {
		return nil, fmt.Errorf("branches.json must contain at least one branch result")
	}
	seen := make(map[string]struct{}, len(results))
	for _, result := range results {
		if _, duplicate := seen[result.BranchID]; duplicate {
			return nil, fmt.Errorf("duplicate branch_id %q", result.BranchID)
		}
		seen[result.BranchID] = struct{}{}
	}
	return results, nil
}

func renderBranchResults(results []BranchResult) string {
	var rendered strings.Builder
	for index, result := range results {
		if index > 0 {
			rendered.WriteString("\n\n")
		}
		fmt.Fprintf(&rendered, "Branch ID: %s\nNotes: %s\nWorktree: %s", result.BranchID, result.Notes, result.Workdir)
	}
	return rendered.String()
}

func decodeStrictJSON(data []byte, target any) error {
	decoder := json.NewDecoder(bytes.NewReader(data))
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(target); err != nil {
		return err
	}
	if err := decoder.Decode(&struct{}{}); err != io.EOF {
		if err == nil {
			return fmt.Errorf("unexpected trailing JSON value")
		}
		return err
	}
	return nil
}

